/* Keep authoring helpers local when loaded as a classic browser script. */
(function () {
/* A43 checkpoint staging; do not index until the complete frozen manifest passes. */
'use strict';
const D=globalThis.RA.D;
const Q=(w,n,s,p,a,b,c,x)=>({id:`${w}.q${n}`,senseId:`${w}.s${s}`,errorType:'meaning',type:'辨义与用法',prompt:p,options:[a,b,c],answer:a,explain:x});
const M=(wrong,right,reason,type='meaning')=>({errorType:type,wrong,right,reason});
const C=(s,domain,en,zh,structure,grammar,rationale)=>({senseId:s,domain,en,zh,structure,grammar,rationale,sourceType:'authored'});
const E=(origin,w)=>({origin,prefix:null,root:null,suffix:null,source:`Etymonline, https://www.etymonline.com/word/${w.toLowerCase().replaceAll(' ','-')}`});
const P=(w,origin,c,m,qs)=>D(w,{etymology:E(origin,w),contexts:Array.isArray(c)?c:[c],mistakes:[m],quiz:qs});
P('harness','Harness 经古法语 harneis 进入英语，早期泛指装备或甲胄，后来专指马具及身体上的系带；动词义由“给……配备”发展而来。',C('harness.s3','能源与工程','The engineers harnessed the steady river current to generate electricity for the remote village.','工程师利用稳定的河流流速，为偏远村庄发电。','The engineers harnessed the steady river current / to generate electricity / for the remote village.','harness 作动词表示控制并利用资源；to 引出用途。','河流动力被转化为电力，体现“利用自然力”。'),M('The village harnessed the river current by leaving it unused and generating no power.','The village harnessed the river current to generate power.','“harness”表示实际利用力量，不能同时说完全未使用。'),[Q('harness',1,1,'On a horse, a harness is mainly used to?','attach and control the animal for work','cover its eyes against sunlight','measure its body temperature','马具用于套住并控制动物。'),Q('harness',2,2,'A climber checks a body harness before?','clipping into a safety rope','polishing a musical instrument','starting a horse race','身体安全带可连接保护绳。'),Q('harness',3,3,'To harness wind power means to?','capture and use the wind’s energy','prevent all wind from blowing','predict tomorrow’s temperature','harness 此处指利用风能。'),Q('harness',4,4,'Before a cart ride, the farmer will harness the horse by?','putting the pulling straps on it','teaching it to swim','removing its reins and tack','给马套上挽具才可拉车。')]);
P('harp','Harp 源自古英语 hearpe，属于古日耳曼语系中表示竖琴的词；“反复谈论”这一动词义常见于 harp on。',C('harp.s2','交流方式','Even after the committee had voted, one member continued to harp on the same minor objection.','即使委员会已经投票，一名成员仍不断纠缠同一个小异议。','Even after the committee had voted / one member continued to harp on / the same minor objection.','harp on 后接反复谈论的主题。','继续纠缠同一异议，符合动词义。'),M('She harped the deadline once and then never mentioned it again.','She harped on the deadline repeatedly.','harp 表示反复唠叨时通常用 harp on，且不是只提一次。','grammar'),[Q('harp',1,1,'A harp produces music when a player?','plucks strings stretched across its frame','strikes a row of metal bells with a bow','blows air through a wooden reed','竖琴靠拨动琴弦发声。'),Q('harp',2,2,'If a speaker keeps harping on a complaint, the speaker?','repeats it tiresomely','forgets it at once','turns it into a song','harp on 指反复唠叨某事。'),Q('harp',3,1,'Which instrument has a triangular frame and many strings?','a harp','a trumpet','a snare drum','竖琴通常有框架和多根弦。'),Q('harp',4,2,'Choose the natural phrase for repeated criticism.','harp on the same mistake','harp the same mistake once','harp away the same mistake','表示反复说应使用 harp on。')]);
P('harpsichord','Harpsichord 是以 harp 与古老键盘乐器名词构成的英语名称，指以拨弦发声、在钢琴普及前广泛使用的键盘乐器。',C('harpsichord.s1','古典音乐','The museum’s harpsichord has a bright, crisp tone because small quills pluck its strings when the keys are pressed.','博物馆里的羽管键琴音色明亮清脆，因为按键时小拨片会拨动琴弦。','The museum’s harpsichord has a bright, crisp tone / because small quills pluck its strings / when the keys are pressed.','because 引出发声原理；quills 是拨弦的小拨片。','按键触发拨片弹弦是羽管键琴区别于现代钢琴的重要机制。'),M('The harpsichord sounded when its hammers struck the strings with changing force.','The harpsichord sounded when its quills plucked the strings.','羽管键琴由拨片拨弦发声，不是钢琴式琴槌击弦。'),[Q('harpsichord',1,1,'What makes a harpsichord sound?','quills plucking its strings','a reed vibrating inside a mouthpiece','air moving through organ pipes only','羽管键琴以拨片拨动琴弦。'),Q('harpsichord',2,1,'A harpsichord is best classified as a?','keyboard instrument','brass instrument','percussion instrument','它有键盘，属于键盘乐器。'),Q('harpsichord',3,1,'Which historical comparison is most accurate?','It was important before the piano became dominant.','It replaced the piano in modern orchestras.','It is a type of electric guitar.','羽管键琴在钢琴普及前曾很重要。'),Q('harpsichord',4,1,'A player normally starts a note on this instrument by?','pressing a key that triggers a plucking action','bowing the strings by hand','blowing into a mouthpiece','按键触发拨弦机构。')]);
P('harridan','Harridan 是带明显贬义的旧式英语称呼；其更早来源并不确定，因此不宜把它拆成确定的词根或构词成分。',C('harridan.s1','人物描写','The novel’s harridan of a landlady berated every tenant who tracked mud into the shared hallway.','小说里那个凶悍刻薄的女房东辱骂每个把泥带进公共走廊的房客。','The novel’s harridan of a landlady / berated every tenant / who tracked mud into the shared hallway.','harridan 是贬称；of a landlady 在此加强人物描写。','刻薄地训斥房客展示了这个贬义称呼的语气。'),M('The review called the warm, patient mentor a harridan as praise for her gentle manner.','The review called the warm, patient mentor a gracious woman.','harridan 是侮辱性称呼，不能用来称赞温和耐心的人。'),[Q('harridan',1,1,'Calling a woman a harridan usually expresses?','contempt for someone seen as harsh and nagging','admiration for her musical talent','neutral respect for her office','该词是针对女性的贬称。'),Q('harridan',2,1,'Which character best fits the word harridan?','a spiteful older woman who constantly berates others','a kindly nurse who quietly comforts patients','a young musician rehearsing alone','刻薄、爱责骂的人更符合此词。'),Q('harridan',3,1,'What tone does harridan carry?','insulting and old-fashioned','formal and complimentary','technical and medical','它带旧式而侮辱性的语气。'),Q('harridan',4,1,'A writer should avoid harridan when describing?','a considerate woman praised for her patience','a character who habitually bullies tenants','a bitter antagonist who scolds everyone','温和耐心者与该贬义词不符。')]);
P('harrow','Harrow 来自古英语中表示耙的词；名词指耕地农具，动词可指用耙松土，也可比喻使人极度痛苦。',C('harrow.s2','情感与记忆','The survivors said that the harrowing testimony about the disaster continued to trouble them for years.','幸存者说，关于那场灾难的痛苦证词多年来一直困扰着他们。','The survivors said / that the harrowing testimony about the disaster / continued to trouble them for years.','harrowing 是 harrow 的形容词形式，表示令人痛苦的；that 从句说明影响。','证词持续造成心灵痛苦，体现比喻性的折磨义。'),M('The harrowed soil was smoothed by a kitchen rake after the farmer finished ploughing the field.','The harrowed soil was broken up by the farm harrow after ploughing.','农田土壤由耙地农具松碎；厨房耙子并非此处合适工具。'),[Q('harrow',1,1,'A farmer drags a harrow over ploughed ground to?','break up and level the soil','cut ripe grain from the stalks','spray seeds with water','耙可松碎、整平翻耕后的土壤。'),Q('harrow',2,2,'A harrowing memory is one that?','causes severe emotional distress','makes a person laugh with relief','is easy to forget immediately','比喻义表示令人痛苦难忘。'),Q('harrow',3,1,'Which object is a harrow?','a toothed farm implement pulled across soil','a machine that milks cows','a tool for pruning tree branches','带齿耙地农具是 harrow。'),Q('harrow',4,2,'In “the images harrowed the family,” harrowed means?','deeply distressed them','helped them cultivate a garden','made them sleep peacefully','动词比喻义为使痛苦、受折磨。')]);
P('harry','Harry 作为动词承接古英语 hergian 一类表示突袭、侵扰的词义，现代常指反复骚扰或不断侵袭。',C('harry.s1','职场与日常','Reporters harried the exhausted mayor with questions as she tried to leave the courthouse.','记者们在疲惫的市长试图离开法院时不断追问她。','Reporters harried the exhausted mayor / with questions / as she tried to leave the courthouse.','harry 是及物动词；with questions 说明骚扰手段。','持续追问使她难以离开，体现反复纠缠。'),M('The reporters harried the mayor by asking one polite question and then leaving her alone.','The reporters harried the mayor by repeatedly surrounding her with questions.','只问一次后离开不符合反复骚扰的意思。'),[Q('harry',1,1,'To harry a witness is to?','bother or pressure the witness repeatedly','praise the witness once in private','write down the witness’s address','harry 强调持续烦扰或施压。'),Q('harry',2,1,'Which scene best illustrates harrying?','A crowd keeps pursuing a minister with demands.','A clerk files one document in an office.','A host thanks a guest and says goodbye.','不断追逐并施压是 harry。'),Q('harry',3,1,'The verb harry most nearly suggests?','repeated harassment','quiet protection','careful measurement','其核心是反复骚扰。'),Q('harry',4,1,'If deadlines harry a team, they?','keep putting the team under pressure','give the team a longer holiday','remove every task from the schedule','deadlines 不断造成压力。')]);
P('harsh','Harsh 的早期来源尚不完全确定；现代英语用它描述苛刻的人或话语，也描述恶劣条件、刺耳感官刺激及刺激性气味或味道。',C('harsh.s4','气味与口味','The cleaner had a harsh chemical smell, so Maya opened the windows and left the room.','清洁剂有刺鼻的化学气味，于是玛雅打开窗户并离开房间。','The cleaner had a harsh chemical smell / so Maya opened the windows / and left the room.','harsh 修饰 smell，表示气味强烈且令人不适。','开窗离开是对刺激性气味的合理反应。'),M('The soft, pleasant vanilla scent was harsh because everyone found it gentle and soothing.','The sharp solvent smell was harsh because it irritated everyone.','人人觉得柔和安抚的香气不应称为 harsh。'),[Q('harsh',1,1,'A harsh judge is most likely?','severe and unkind in judgment','warm and forgiving toward every error','unable to make any decision','harsh 描写严厉苛刻的人。'),Q('harsh',2,2,'A harsh winter is one with?','unpleasantly severe conditions','mild days and gentle rain','no change in temperature','环境义表示条件严酷。'),Q('harsh',3,3,'A harsh sound would be?','rough and unpleasant to hear','soft and melodious','completely silent','感官义可指刺耳、不悦耳。'),Q('harsh',4,4,'Which drink is likely to taste harsh?','an intensely bitter, irritating spirit','a mild, smooth herbal tea','plain water with no strong taste','刺激而令人不适的口味可称 harsh。')]);
P('harshly','Harshly 由 harsh 加副词后缀 -ly 构成，可表示以苛刻方式对待，也可形容声音粗厉刺耳。',C('harshly.s2','声音描写','The old speaker crackled harshly whenever the volume was turned above the halfway mark.','音量一旦调过一半，旧音箱就会发出刺耳的噼啪声。','The old speaker crackled harshly / whenever the volume was turned / above the halfway mark.','harshly 修饰 crackled，描写声音质地。','音量升高时声音变得刺耳，体现副词的声音义。'),M('The chair harshly the applicant after listening to the answer.','The chair harshly criticized the applicant after listening to the answer.','harshly 是副词，需修饰动词；原句缺少谓语动词。','grammar'),[Q('harshly',1,1,'To judge someone harshly is to judge them?','in a severe and unkind way','with patient generosity','without forming any opinion','harshly 表示严厉苛刻地。'),Q('harshly',2,2,'If a violin sounds harshly, its tone is?','rough and unpleasant to hear','smooth and quiet','silent between notes','声音义指粗厉刺耳。'),Q('harshly',3,1,'Which sentence uses harshly as an adverb?','The manager spoke harshly to the crew.','The manager harshly speech was brief.','The harshly manager arrived late.','副词修饰 spoke。'),Q('harshly',4,2,'A reviewer who harshly dismisses a proposal does so?','with severe, cutting criticism','with wholehearted approval','without reading it aloud','严厉否定对应 harshly。')]);
P('harshness','Harshness 由 harsh 加名词后缀 -ness 构成，指严酷或苛刻的性质；可谈待人方式，也可谈环境的艰苦程度。',C('harshness.s1','生存条件','The harshness of the desert winter surprised the hikers, who had packed for warm weather.','沙漠冬季的严酷令徒步者吃惊；他们原本按温暖天气准备了行装。','The harshness of the desert winter / surprised the hikers / who had packed for warm weather.','harshness 是抽象名词，of 短语说明严酷来自冬季环境。','准备不足显示他们低估了环境的艰苦。'),M('The harshness of her kindness comforted the frightened child because she was gentle.','Her kindness comforted the frightened child because she spoke gently.','kindness 表示善意，不能将温柔安慰描述为 harshness。'),[Q('harshness',1,1,'The harshness of a climate refers to its?','severe and difficult conditions','pleasant mildness throughout the year','ability to produce musical notes','harshness 表示严酷、恶劣的程度。'),Q('harshness',2,1,'What might reduce the harshness of a winter?','shelter, warm clothing, and reliable heating','removing every roof from houses','spending more time in freezing rain','保暖与庇护可缓解冬季严酷。'),Q('harshness',3,1,'Harshness in a supervisor’s manner suggests?','unnecessary severity toward staff','steady kindness and patience','a lack of any interaction','对待方式上的 harshness 即苛刻。'),Q('harshness',4,1,'Which phrase uses harshness naturally?','the harshness of the mountain conditions','the harshness of her gentle welcome','the harshness of a silent color','恶劣山地条件可有 harshness。')]);
P('hart','Hart 源自古英语 heorot，历史上指成熟的雄性赤鹿；它现在多见于文学、地名或固定表达。',C('hart.s1','野生动物','At dawn, a hart stepped from the woodland edge, its mature antlers visible against the pale sky.','黎明时，一只成年雄赤鹿从林缘走出，成熟的鹿角映在淡色天空前。','At dawn, a hart stepped from the woodland edge / its mature antlers visible / against the pale sky.','hart 是动物名词；独立分句补充鹿角特征。','成熟雄鹿与长成的鹿角相符。'),M('The wildlife guide identified the young female deer as a hart because it had no antlers.','The wildlife guide identified the mature male red deer as a hart.','hart 指成年雄赤鹿，不能用于没有鹿角的幼年雌鹿。'),[Q('hart',1,1,'A hart is traditionally a?','mature male red deer','young female rabbit','domesticated goat','hart 指成年雄赤鹿。'),Q('hart',2,1,'Which field guide entry could correctly mention a hart?','a fully grown stag with developed antlers','a doe nursing two fawns','a lamb grazing by a fence','成熟雄鹿可称 hart。'),Q('hart',3,1,'The word hart is most likely to appear in?','literary or traditional descriptions of deer','instructions for repairing radios','modern medical prescriptions','它较常见于文学或传统用语。'),Q('hart',4,1,'Which detail best supports calling the animal a hart?','It is a mature male red deer.','It is a young female hare.','It is a fish in a freshwater pond.','物种、性别和成熟阶段都应符合。')]);
P('harvest','Harvest 源于古英语 hærfest，最初与秋季相关，后来指收割季、收成，也可作动词表示采收或获取资源。',C('harvest.s4','医学研究','After the consent forms were signed, the laboratory harvested a small number of cells for analysis.','在签署同意书后，实验室采集了少量细胞用于分析。','After the consent forms were signed / the laboratory harvested a small number of cells / for analysis.','harvest 作动词可表示采集生物材料；for analysis 说明用途。','细胞被有计划地采集并用于研究，符合该义。'),M('The team harvested the cells before receiving consent, then described the procedure as properly authorized.','The team harvested the cells only after receiving consent.','未取得同意就采集细胞，不能说程序获得了授权。'),[Q('harvest',1,1,'The harvest is the time or process of?','gathering crops from fields','planting seeds in a greenhouse','selling farm equipment','harvest 名词常指收割及收成。'),Q('harvest',2,2,'A “harvest of discoveries” means?','results gained from sustained work','a field full of ripe wheat only','a set of unused tools','比喻义指工作成果。'),Q('harvest',3,3,'To harvest apples is to?','pick and collect them','prune every tree trunk','bury them in the soil','动词 harvest 可指采摘收集。'),Q('harvest',4,4,'In a laboratory, to harvest cells means to?','collect cells for a specified use','grow crops outdoors','destroy every sample without examination','生物医学语境中可指采集细胞。')]);
P('harvester','Harvester 由 harvest 加施事或器具后缀 -er 构成，既可指收割机，也可指采收作物的人。',C('harvester.s1','农业设备','The combine harvester cut the wheat and gathered the grain into a tank as it crossed the field.','联合收割机穿过田地时割下小麦，并把谷粒收进储仓。','The combine harvester cut the wheat / and gathered the grain into a tank / as it crossed the field.','combine harvester 指联合收割机；as 从句交代机器工作的同时过程。','割下作物并收集谷粒说明这里指机器。'),M('The harvester planted the wheat by pouring grain into the storage tank after cutting it.','The harvester gathered the cut wheat into the storage tank.','把谷物装入仓内是收割收集，不是播种。'),[Q('harvester',1,1,'A combine harvester is a machine that?','cuts crops and gathers the grain','waters plants and tests the soil','packs seeds into envelopes','联合收割机兼有收割和收集功能。'),Q('harvester',2,2,'A seasonal harvester hired by a farm is a?','person who gathers crops','machine used only for irrigation','buyer of imported fertilizer','harvester 也可指采收者。'),Q('harvester',3,1,'Which clue points to the machine sense?','It drove through wheat, cutting and collecting grain.','She bent down to pick berries by hand.','He negotiated the crop price at market.','驾驶机器完成收割的是机器义。'),Q('harvester',4,2,'A farmer may call a worker a harvester because the worker?','collects ripe produce from the field','repairs the barn roof','writes the weather forecast','人工采收作物的人也叫 harvester。')]);
P('hassle','Hassle 在20世纪美国英语中成为口语词，其更早构词来源不确定；名词指恼人的麻烦或争执，动词指烦扰、纠缠。',C('hassle.s2','顾客服务','The airline agent hassled the passenger for another receipt even though the original had already been submitted.','尽管乘客已经提交了原始收据，航空公司职员仍纠缠着要另一张。','The airline agent hassled the passenger / for another receipt / even though the original had already been submitted.','hassle 作动词表示不断烦扰；for 引出被索要之物。','重复索取已交过的收据，体现令人厌烦的纠缠。'),M('The clerk hassled the applicant once, accepted the complete form, and never troubled her again.','The clerk hassled the applicant by repeatedly demanding documents she had already filed.','只问一次并立即接受材料不足以构成反复烦扰。'),[Q('hassle',1,1,'A paperwork hassle is usually?','an annoying problem that takes effort','a pleasant surprise with no work','a formal award for good service','hassle 名词指令人厌烦的麻烦。'),Q('hassle',2,2,'If a caller hassles you, the caller?','keeps bothering or pressuring you','quietly sends one requested file','thanks you and ends the call','动词强调烦扰或纠缠。'),Q('hassle',3,1,'Which is most likely to be a hassle?','having to resubmit the same missing form several times','receiving a correctly completed form at once','finishing a short task ahead of schedule','反复补交材料是麻烦。'),Q('hassle',4,2,'Choose the natural use:','The repair hassle delayed our trip.','The repair hassled was bright blue.','We hassle the receipt into a drawer.','hassle 可作名词修饰延误旅行的麻烦。')]);
P('haste','Haste 经古法语 haste 进入英语，指匆忙；在 without haste 中可表示不慌不忙，但常与过急导致的草率相连。',C('haste.s2','工作决策','In her haste to submit the report before noon, Lina skipped the final check and left two figures unreconciled.','莉娜急着在中午前交报告，跳过了最后检查，留下两处数字未核对。','In her haste to submit the report before noon / Lina skipped the final check / and left two figures unreconciled.','in one’s haste to do 表示急于做某事；and 连接结果。','仓促导致检查遗漏，体现匆忙带来的草率。'),M('In his haste, he carefully checked every calculation twice and waited a day before sending the file.','In his haste, he sent the file before checking the calculations.','仔细复核并等待一天体现谨慎，不符合 haste 所表达的仓促。'),[Q('haste',1,1,'Working in haste means working?','with excessive speed or urgency','at a deliberately slow pace','only after a long vacation','haste 指匆忙、急速。'),Q('haste',2,2,'A mistake made in haste is often caused by?','rushing without enough care','checking every detail repeatedly','taking extra time to reflect','仓促容易导致草率失误。'),Q('haste',3,1,'Which phrase is idiomatic?','Make haste before the gate closes.','Make a haste before the gate closes.','Do haste before the gate closes.','make haste 是惯用表达。'),Q('haste',4,2,'“There is no need for haste” tells someone to?','avoid rushing','finish immediately at any cost','stop working forever','no need for haste 即不必赶忙。')]);
P('hasten','Hasten 由 haste 加动词后缀 -en 构成，可表示加快进程，也可表示催促某人或某事。',C('hasten.s1','项目进度','A revised timetable hastened the repairs, allowing the bridge to reopen two weeks ahead of schedule.','修订后的时间表加快了维修进程，使桥梁提前两周重新开放。','A revised timetable hastened the repairs / allowing the bridge to reopen / two weeks ahead of schedule.','hasten 作及物动词，宾语 repairs 表示被加快的进程。','工程进度被提前，体现“加速”。'),M('The delay hastened the repairs because workers stopped and postponed every task.','The extra crew hastened the repairs by completing several tasks in parallel.','停工延期会拖慢维修而非加快。'),[Q('hasten',1,1,'To hasten a process is to?','make it happen sooner or faster','make it last longer without progress','hide it from everyone involved','hasten 表示加速或促成提前发生。'),Q('hasten',2,1,'Which action would hasten a rescue?','bringing in another trained search team','closing the search area for a month','discarding the only location map','增加搜救力量可加快行动。'),Q('hasten',3,1,'In “the news hastened her decision,” the news?','caused her to decide sooner','made her forget the decision','delayed the decision indefinitely','消息促使她更快作出决定。'),Q('hasten',4,1,'Which verb is closest to hasten here?','accelerate','postpone','conceal','hasten 在此最接近加快。')]);
P('hasty','Hasty 由 haste 加形容词后缀 -y 构成，可描述行动仓促，也可批评未经充分考虑的判断。',C('hasty.s1','审慎决策','The board made a hasty promise before checking whether the project could be completed within the budget.','董事会没有先核实项目能否在预算内完成，就仓促作出承诺。','The board made a hasty promise / before checking / whether the project could be completed within the budget.','hasty 修饰 promise，突出作出承诺前考虑不足。','先承诺、后核实预算显示决定太仓促。'),M('After months of careful review, the board made a hasty decision based on full evidence and deliberate discussion.','Without reviewing the evidence, the board made a hasty decision.','经过数月审查并充分讨论，不符合“仓促”的含义。'),[Q('hasty',1,1,'A hasty conclusion is reached?','too quickly, without enough thought','after a careful review of all evidence','only when every fact is certain','hasty 常指过快且考虑不足。'),Q('hasty',2,1,'Which choice is hasty?','signing a contract before reading its terms','comparing two offers over several days','asking a lawyer to review a clause','未读条款就签约显得仓促。'),Q('hasty',3,1,'A hasty meal is generally eaten?','quickly because there is little time','slowly during a long celebration','only after a recipe is translated','形容进餐时指匆匆吃完。'),Q('hasty',4,1,'Which phrase warns against being hasty?','Take time to check the facts first.','Decide now without looking at the file.','Ignore the evidence and guess.','核实事实并花时间能避免仓促。')]);
P('hat','Hat 源自古英语 hætt，历史上与头部覆盖物有关；现代主要指帽子，也可比喻一个人的职业或身份角色。',C('hat.s2','身份与职责','During the merger, Nia wore her legal hat in the morning and her project-manager hat in the afternoon.','合并期间，妮娅上午以法律顾问身份工作，下午则承担项目经理职责。','During the merger / Nia wore her legal hat in the morning / and her project-manager hat in the afternoon.','wear a hat 可比喻承担一种身份或职责；并列结构对照两种角色。','两种职业职责而非实际帽子，是比喻义。'),M('He put on his accountant hat to keep the rain off his head.','He put on a wide-brimmed hat to keep the rain off his head.','保护头部免受雨淋描述实际帽子，不是职业角色的比喻义。'),[Q('hat',1,1,'A sun hat is worn mainly to?','cover and protect the head','keep food warm on a plate','carry books over the shoulder','hat 是戴在头上的覆盖物。'),Q('hat',2,2,'If a manager wears two hats, the manager?','has two different roles or responsibilities','owns exactly two pieces of headwear','is leaving the company today','wear two hats 常比喻承担多个角色。'),Q('hat',3,3,'To hat a performer in a costume workshop would mean to?','put a hat on the performer','assign a new job title','measure the height of the stage','动词 hat 可指给某人戴帽子。'),Q('hat',4,2,'Which sentence uses hat figuratively?','As treasurer, he wore a different hat at the meeting.','She bought a wool hat for the cold walk.','The hat fell off the shelf.','担任 treasurer 是职责角色的比喻用法。')]);
P('hatch','Hatch 源自古英语 hæccan 一类表示孵化的词；现代既可指蛋孵出或孵蛋，也可指秘密策划，名词则是舱口或小开口。',C('hatch.s2','秘密计划','The rivals hatched a plan to divert the shipment, but a guard noticed their forged delivery papers.','对手策划了转移货物的计划，但一名守卫发现了他们伪造的送货单。','The rivals hatched a plan / to divert the shipment / but a guard noticed their forged delivery papers.','hatch a plan 是“策划计划”的搭配；but 引出阻碍。','计划是秘密策划的，符合动词的引申义。'),M('The hen hatched a plot by keeping the eggs warm until the chicks emerged.','The conspirators hatched a plot to steal the shipment.','保温孵蛋是孵化义，不是策划阴谋。'),[Q('hatch',1,1,'When an egg hatches, the young animal?','comes out of the egg','builds a nest from stone','returns to the shell as an adult','hatch 的生物义是孵出、破壳。'),Q('hatch',2,2,'To hatch a secret plan is to?','devise it, often quietly','announce that no plan exists','repair a hatch on a ship','hatch a plan 表示秘密策划。'),Q('hatch',3,3,'A ship’s hatch is an?','opening with a cover in its deck','anchor used to stop the ship','instrument that measures wind','船舱口是甲板上的带盖开口。'),Q('hatch',4,4,'A hatch in a floor could provide?','a small access opening between levels','a decorative painting on a wall','a window that cannot be opened','地板上的 hatch 可作检修或通行开口。')]);
P('hatchery','Hatchery 由 hatch 加地点后缀 -ery 构成，指人工孵化鱼卵或鸟蛋并在早期培育幼体的设施。',C('hatchery.s1','野生动物保护','The hatchery released young salmon into the stream after staff checked their health and tagged a sample.','工作人员检查幼鲑健康状况并给样本做标记后，孵化场将幼鲑放入溪流。','The hatchery released young salmon into the stream / after staff checked their health / and tagged a sample.','hatchery 指孵化和初期培育设施；after 引出放流前步骤。','幼鲑在此培育后放流，符合设施用途。'),M('The hatchery released salmon eggs into the office printer so they could hatch there.','The hatchery incubated the salmon eggs in controlled tanks before releasing the fry.','办公室打印机不是孵化鱼卵的受控设施。'),[Q('hatchery',1,1,'A fish hatchery is a place where?','eggs are incubated and young fish are raised','adult fish are dried for market','boats are stored during winter','孵化场培育鱼卵和幼鱼。'),Q('hatchery',2,1,'Why might a conservation group use a hatchery?','to raise young fish before releasing them','to stop eggs from developing','to replace the river with concrete','培育幼鱼后放流有助于保护种群。'),Q('hatchery',3,1,'Which task belongs at a hatchery?','monitoring water conditions around developing eggs','printing office invoices','repairing a highway bridge','孵化需要监控卵周围的水环境。'),Q('hatchery',4,1,'Hatchery is a place noun formed from the idea of?','hatching and raising young animals','harvesting ripe grain','training adult athletes','其词义来自孵化、培育幼体。')]);
P('hatchet','Hatchet 经古法语 hachette 进入英语，是 hache“斧”的小称形式，指可单手使用的短柄斧。',C('hatchet.s1','露营装备','The camper used a hatchet to split kindling, keeping the small blade pointed away from his hand.','露营者用短柄斧劈引火木，并让小斧刃避开自己的手。','The camper used a hatchet to split kindling / keeping the small blade / pointed away from his hand.','hatchet 是单手短柄斧；to split 引出工具用途。','劈小块引火木适合用短柄斧。'),M('She used a hatchet to shave a delicate portrait into a paper napkin.','She used a fine craft knife to cut a delicate portrait into a paper napkin.','短柄斧不适合精细刻纸；应选小型工艺刀。'),[Q('hatchet',1,1,'A hatchet is a?','small one-handed axe','long-handled scythe for cutting hay','blunt tool for tightening bolts','hatchet 是小型单手斧。'),Q('hatchet',2,1,'Which job suits a hatchet?','splitting small pieces of kindling','mowing a broad meadow','drilling a narrow hole in metal','短柄斧适合劈小块木柴。'),Q('hatchet',3,1,'Compared with a full-sized axe, a hatchet is usually?','smaller and easier to carry in one hand','larger and mounted on a tractor','designed to cut grass with a curved blade','它通常更小，可单手使用。'),Q('hatchet',4,1,'In “bury the hatchet,” the hatchet stands for?','an end to a quarrel','a plan to build a fence','a harvest of grain','习语中埋斧头比喻和解。')]);
P('hatchling','Hatchling 由 hatch 加表示幼小个体的后缀 -ling 构成，指刚从卵中孵出的鸟、爬行动物或鱼类幼体。',C('hatchling.s1','动物观察','The turtle hatchlings crossed the warm sand toward the sea while volunteers kept the path clear.','海龟幼崽穿过温暖的沙滩爬向大海，志愿者则清理着它们的路线。','The turtle hatchlings crossed the warm sand / toward the sea / while volunteers kept the path clear.','hatchlings 是复数名词，指刚孵出的幼体；while 引出同时发生的保护行动。','刚出壳并向海边移动的幼龟是 hatchlings。'),M('The hatchling had lived in the forest for ten years before its egg cracked.','The hatchling emerged from its egg and entered the forest.','hatchling 指刚孵出的幼体，不可能在蛋未孵出前独自在森林生活多年。'),[Q('hatchling',1,1,'A hatchling is an animal that has?','just emerged from an egg','just finished a long migration as an adult','never developed inside an egg','hatchling 指刚孵出的幼体。'),Q('hatchling',2,1,'Which is a hatchling?','a newly emerged sea turtle','a fully grown horse','a newborn puppy delivered alive','海龟刚出壳后称 hatchling。'),Q('hatchling',3,1,'A bird hatchling would most likely be found?','newly out of its egg in a nest','inside a mature tree trunk','swimming as an adult whale','它刚离开鸟蛋，常在巢里。'),Q('hatchling',4,1,'Why might conservationists protect hatchlings on a beach?','they are newly emerged and vulnerable','they are old enough to guard the whole coast','they are planted as dune grass','幼体刚孵出，容易受到伤害。')]);
P('hatchway','Hatchway 由 hatch 与 way 组合，指船甲板或地板上供人或货物通过的舱口、通道开口。',C('hatchway.s1','船舶与通行','A deckhand secured the hatchway before the storm so waves could not flood the compartment below.','暴风雨来临前，水手固定好了舱口，以免海浪淹没下层舱室。','A deckhand secured the hatchway before the storm / so waves could not flood / the compartment below.','hatchway 是带盖通道开口；so 引出封闭它的目的。','固定舱口以阻止海水进入下层，符合船用开口义。'),M('The captain opened the hatchway to seal off the only passage between decks.','The captain closed the hatchway to seal off the passage between decks.','打开开口无法封住通道，动作和目的相反。'),[Q('hatchway',1,1,'A ship’s hatchway is an opening used to?','reach spaces through the deck','steer the rudder from the shore','measure the depth of the sea','船舱口用于出入甲板下空间。'),Q('hatchway',2,1,'A worker climbs through a hatchway to?','pass between levels or compartments','raise the ship’s sail','paint a number on the hull','hatchway 是舱室通道开口。'),Q('hatchway',3,1,'Which feature might have a hatchway?','a ship’s deck with a covered access opening','a smooth wall with no door or gap','a field planted with wheat','船甲板常有盖式通道开口。'),Q('hatchway',4,1,'Before rough seas, a crew might secure a hatchway to?','keep water out of the compartment below','let more waves enter the hold','make the ship travel faster by itself','固定舱口可防止海水涌入。')]);
P('hate','Hate 源自古英语 hatian，现代既可作动词表示强烈厌恶或不愿，也可作名词表示憎恨或所憎恶的人、事物。',C('hate.s2','偏好与意愿','I hate driving through the city at rush hour, so I take the train whenever my schedule allows.','我讨厌在高峰时段开车穿过市区，所以时间允许时总是坐火车。','I hate driving through the city at rush hour / so I take the train / whenever my schedule allows.','hate 可接动名词，表示不喜欢做某事；so 表示选择的结果。','避开高峰驾驶表达的是对某项活动的厌恶。'),M('She hate to waits in line, so she bought a ticket online.','She hates waiting in line, so she bought a ticket online.','第三人称单数需用 hates；hate 后接动名词 waiting。','grammar'),[Q('hate',1,1,'If you hate a person, you?','feel intense dislike toward that person','feel no emotion about that person','admire everything that person does','hate 作动词可表示强烈憎恶。'),Q('hate',2,2,'“I hate to interrupt” usually means?','I am sorry or reluctant to interrupt','I enjoy interrupting people','I have never spoken before','hate to do 可表示不愿或抱歉要做某事。'),Q('hate',3,3,'In “There was hate in his voice,” hate is?','a strong hostile feeling','a task that must be completed','a mild preference for music','hate 作名词指强烈敌意。'),Q('hate',4,4,'A person may call a hated object “a hate” to mean?','something that person strongly dislikes','something that person invented','a person’s legal name','hate 的名词也可指所憎恶的人或事物。')]);
P('hatred','Hatred 由 hate 加抽象名词后缀 -red 构成，表示强烈而持久的憎恨。',C('hatred.s1','冲突调解','Years of hatred between the neighbors eased only after both families met and settled the boundary dispute.','邻里之间多年的仇恨，直到两家见面解决了边界争端后才有所缓和。','Years of hatred between the neighbors / eased only after both families met / and settled the boundary dispute.','hatred 是不可数抽象名词；between 标明相互仇恨的双方。','长期冲突形成并经和解减轻的强烈敌意，符合其含义。'),M('The two rivals felt hatred for each other, so they admired and trusted one another completely.','The two rivals felt respect for each other, so they admired and trusted one another.','完全信任和欣赏与强烈仇恨相矛盾。'),[Q('hatred',1,1,'Hatred is best described as?','a very strong feeling of dislike','a brief moment of surprise','a formal written agreement','hatred 指强烈的憎恨。'),Q('hatred',2,1,'Which situation could show hatred?','a feud that leads one side to wish harm on the other','a friendly wave between former classmates','a neutral report of the weather','怀有伤害对方的敌意体现仇恨。'),Q('hatred',3,1,'Which verb naturally collocates with hatred?','feel','manufacture','measure in liters','常说 feel hatred。'),Q('hatred',4,1,'If hatred eases, the hostile feeling?','becomes less intense','turns into a physical object','automatically grows stronger','ease 表示仇恨减轻。')]);
P('haughty','Haughty 经古法语 haut“高”进入英语，形容冷傲自大、以高人一等的态度对待他人。',C('haughty.s1','社交互动','The haughty investor barely looked at the volunteers and spoke as if their work were beneath notice.','那个傲慢的投资人几乎不看志愿者，说话时仿佛他们的工作不值一提。','The haughty investor barely looked at the volunteers / and spoke / as if their work were beneath notice.','haughty 修饰 investor；as if 从句展现其居高临下态度。','轻视他人、认为对方不值一提是傲慢表现。'),M('The haughty host listened modestly, thanked every guest, and never treated anyone as inferior.','The haughty host dismissed the guests and treated their concerns as unimportant.','谦逊倾听且尊重所有客人不符合 haughty 的傲慢义。'),[Q('haughty',1,1,'A haughty person behaves as if?','they are superior to other people','everyone else deserves equal attention','they have no opinion about status','haughty 指冷傲自大的态度。'),Q('haughty',2,1,'Which response sounds haughty?','“I will not waste time listening to people like you.”','“Tell me what you think; I may be mistaken.”','“Thank you for explaining your concern.”','轻蔑拒绝倾听体现傲慢。'),Q('haughty',3,1,'A haughty expression is most likely?','cold and condescending','warm and welcoming','confused and apologetic','haughty 表情可能显得冷傲。'),Q('haughty',4,1,'Which is the opposite of a haughty manner?','humble respect for others','cold superiority','dismissive contempt','谦逊尊重与傲慢相反。')]);
P('haul','Haul 的更早来源并不完全确定；现代可指用力拖拉、用车辆运输，也可作名词指查获物或一次行动所得。',C('haul.s2','货运与物流','Two trucks haul timber from the mill to the port, where it is loaded onto a ship.','两辆卡车把木材从锯木厂运到港口，再装上船。','Two trucks haul timber from the mill to the port / where it is loaded onto a ship.','haul 作动词表示用车辆运输；from 和 to 标示路线两端。','卡车将货物从一个地点运往另一个地点，体现运输义。'),M('The truck hauled the timber by leaving the entire load at the mill.','The truck hauled the timber from the mill to the port.','把货留在起点没有完成运输。'),[Q('haul',1,1,'To haul a heavy crate across a room is to?','pull or drag it with effort','fold it into a smaller shape','weigh it without moving it','haul 表示费力拉动。'),Q('haul',2,2,'A company that hauls freight usually?','transports goods by vehicle','grows crops in a greenhouse','repairs musical instruments','运输货物是 haul 的动词义。'),Q('haul',3,3,'A police haul of stolen goods is?','the amount of goods recovered','the vehicle used to tow a car','the officer’s official schedule','haul 可指查获的一批赃物。'),Q('haul',4,4,'After a long fishing trip, “a good haul” means?','a large amount of fish caught','a rope used to pull a boat','a delay caused by bad weather','haul 名词也可指一次所得或收获。')]);
P('hauler','Hauler 由 haul 加施事后缀 -er 构成，指以运输货物为业的人或公司，也可指承担拖运工作的车辆。',C('hauler.s1','货运行业','The hauler contracted to move the steel beams from the rail yard to the construction site overnight.','这家运输公司签约在夜间把钢梁从铁路货场运到工地。','The hauler contracted to move the steel beams / from the rail yard / to the construction site overnight.','hauler 作名词指承运人或运输公司；to move 引出合同任务。','签约运输钢梁的公司就是 hauler。'),M('The hauler promised to transport the beams, but the company only baked bread at the depot.','The hauler promised to transport the beams by truck overnight.','只烤面包的公司没有承担运输货物的业务。'),[Q('hauler',1,1,'A freight hauler earns a living by?','moving goods, often by truck','writing novels about trains','growing timber in a forest','hauler 指运输货物的人或公司。'),Q('hauler',2,1,'Which business is a hauler?','a firm that carries steel between warehouses','a bakery selling bread at a station','a clinic treating injured drivers','承运货物的公司属于 hauler。'),Q('hauler',3,1,'A truck hauler is connected with?','transporting heavy loads','editing newspaper headlines','raising fish eggs','hauler 与拖运、货运相关。'),Q('hauler',4,1,'Why might a factory hire a hauler?','to deliver equipment to another site','to judge the color of its walls','to compose music for its staff','工厂会雇承运商运送设备。')]);
P('haulier','Haulier 由 haul 加表示从事者的后缀 -ier 构成，是英式英语中指公路货运商或货运承运人的词。',C('haulier.s1','英式交通','The haulier collected the furniture in Leeds and delivered it to the customer’s new home in Bristol.','这家公路货运商在利兹收取家具，并送到顾客位于布里斯托尔的新家。','The haulier collected the furniture in Leeds / and delivered it / to the customer’s new home in Bristol.','haulier 指承运货物的人或公司；collected 与 delivered 描写运输两端。','跨城收取并送达家具体现货运商身份。'),M('The British haulier delivered the furniture by keeping it in Leeds and refusing to transport it.','The British haulier delivered the furniture from Leeds to Bristol.','不运输货物就没有履行承运工作。'),[Q('haulier',1,1,'In British English, a haulier is usually?','a person or company that transports goods by road','a passenger waiting for a train','a farmer who harvests hay','haulier 是英式货运承运人。'),Q('haulier',2,1,'Which vehicle might a haulier operate?','a lorry carrying furniture between cities','a sailing boat used only for racing','a bicycle used in a park','公路货运商常使用卡车或货车。'),Q('haulier',3,1,'Haulier and hauler are related because both involve?','hauling or transporting loads','hatching eggs in an incubator','wearing a formal hat','两词都来自 haul 的运输义。'),Q('haulier',4,1,'A shop needs a haulier when it must?','move stock from a warehouse to its store','choose a title for a newspaper story','treat a patient’s injury','运输库存是承运人的职责。')]);
P('haunch','Haunch 源自古法语 hanche，指人体的臀部与大腿上部，也可指动物相应的后腿部位。',C('haunch.s1','解剖与动作','The runner stretched her left haunch after the steep climb because the upper leg felt tight.','陡坡攀爬后，跑者拉伸左侧臀部与大腿上部，因为那里感觉紧绷。','The runner stretched her left haunch / after the steep climb / because the upper leg felt tight.','haunch 指髋部和大腿上部；because 说明拉伸原因。','上腿与髋部紧绷说明所指身体部位。'),M('The runner massaged her haunch behind her ear after the climb.','The runner massaged her haunch at the top of her leg after the climb.','haunch 位于髋部和大腿上部，不在耳后。'),[Q('haunch',1,1,'A person’s haunch is around the?','hip and upper part of the leg','wrist and palm','neck and jaw','haunch 指臀髋及大腿上部。'),Q('haunch',2,1,'A butcher may sell a haunch of venison from the deer’s?','rear leg and hip area','front paw','tail feathers','动物 haunch 指后腿与臀髋附近。'),Q('haunch',3,1,'Which exercise might stretch a tight haunch?','a lunge that opens the hip and upper leg','a wrist curl with a small weight','a blink repeated ten times','髋部弓步可拉伸大腿上部。'),Q('haunch',4,1,'Where would a doctor examine a painful haunch?','near the hip and upper thigh','inside the ear canal','between the fingers','检查部位应在髋部和上腿。')]);
P('haunt','Haunt 经古法语 hanter“常去”进入英语，既可指鬼魂出没或记忆缠扰，也可指常去某地；名词可指常去的场所。',C('haunt.s3','生活习惯','During college, the chess team haunted a small café near campus every Friday night.','上大学时，棋队每周五晚上都常去校园附近的一家小咖啡馆。','During college / the chess team haunted a small café near campus / every Friday night.','haunt 作动词接地点，表示经常去；every Friday night 表示规律性。','固定每周到访符合“常去某地”的义项。'),M('The team haunted the café once in ten years and never returned.','The team haunted the café every Friday and knew the staff by name.','十年只去一次不符合经常光顾。'),[Q('haunt',1,1,'A ghost is said to haunt a house when it?','appears there repeatedly','owns the house legally','repairs its roof every spring','鬼魂义指经常显现或出没。'),Q('haunt',2,2,'A painful memory that haunts someone?','keeps troubling the person’s mind','is forgotten before it happens','belongs to someone else’s house','haunt 可指记忆持续困扰心灵。'),Q('haunt',3,3,'A student who haunts a library?','visits it very often','works there as a ghost','has never entered it','动词 haunt 也指常去某地。'),Q('haunt',4,4,'A musician’s old haunt is probably?','a place the musician often visited','a spirit that follows the musician','a song that has never been played','名词 haunt 指常去的地方。')]);
P('haunted','Haunted 是 haunt 的过去分词形容词，既可指被认为有鬼魂出没，也可指被反复回想的记忆、恐惧或内疚所困扰。',C('haunted.s2','心理状态','Years later, the witness still felt haunted by the decision to leave her friend behind during the evacuation.','多年以后，证人仍被疏散时把朋友留在身后的决定所困扰。','Years later / the witness still felt haunted / by the decision to leave her friend behind during the evacuation.','be haunted by 后接持续折磨人的记忆或内疚来源。','多年后仍无法释怀，体现心理上的缠扰义。'),M('He was haunted by the memory, so he had completely forgotten it and never thought of it again.','He was haunted by the memory, which returned to him whenever he was alone.','彻底忘记且不再想起与被记忆缠扰相矛盾。'),[Q('haunted',1,1,'A haunted house is traditionally believed to be?','visited by ghosts','built entirely underground','owned by a family of musicians','haunted 的常见形容词义是闹鬼的。'),Q('haunted',2,2,'A person haunted by guilt is?','troubled by guilt that keeps returning','pleased that no mistake occurred','unable to remember any event','心理义表示持续受内疚困扰。'),Q('haunted',3,1,'Which scene feels haunted in the ghost sense?','a spirit is believed to appear in the empty manor','a traveler remembers a difficult choice','a tenant paints a bright kitchen','鬼魂在宅中出现对应闹鬼义。'),Q('haunted',4,2,'“She looked haunted by the past” suggests she?','was still deeply troubled by old events','had never experienced any difficulty','was living in a haunted castle','该表达通常指往事困扰她。')]);
P('haunting','Haunting 由 haunt 加 -ing 构成，可作形容词，形容令人难忘、萦绕心头或带有幽异感的景象、声音和作品。',C('haunting.s1','艺术与记忆','A haunting melody followed the documentary’s final scene, and viewers hummed it long after leaving the theater.','纪录片最后一幕之后响起一段萦绕心头的旋律，观众离开影院很久仍哼着它。','A haunting melody followed the documentary’s final scene / and viewers hummed it / long after leaving the theater.','haunting 修饰 melody，表示旋律强烈触动人心、难以忘怀。','观众离场后仍记得并哼唱，证明旋律挥之不去。'),M('The melody was haunting because every listener forgot it before the first note ended.','The melody was haunting because listeners kept remembering it for days.','很快遗忘与令人萦绕难忘的含义相反。'),[Q('haunting',1,1,'A haunting tune is one that?','stays strongly in the listener’s memory','is too quiet to be heard','changes into a written report','haunting 可形容萦绕心头的旋律。'),Q('haunting',2,1,'Which image might be called haunting?','an empty station lit by a single fading lamp','a clear shopping list on a white page','a bright room with no striking details','幽静、令人难忘的画面可称 haunting。'),Q('haunting',3,1,'The adjective haunting often suggests an effect that is?','powerful and difficult to forget','ordinary and immediately dismissed','purely mathematical','其核心是强烈而难忘的感受。'),Q('haunting',4,1,'A haunting voice in a song may?','linger in the mind after the song ends','make the lyrics disappear from the recording','prevent the song from making any sound','歌声结束后仍萦绕记忆。')]);
P('have','Have 源自古英语 habban“持有”；它还用于吃喝、活动、使某事被完成、构成完成时及表达义务 have to。',[C('have.s4','服务与安排','We had the broken lock replaced before the guests arrived, so the front door could close securely.','客人到来前，我们请人更换了坏锁，因此前门可以安全关闭。','We had the broken lock replaced / before the guests arrived / so the front door could close securely.','have + 宾语 + 过去分词表示安排或促使某事被完成。','安排别人更换锁，而不是自己“拥有更换”，体现使役结构。'),C('have.s5','英语语法','By the time the train arrived, the staff had checked every ticket and opened the platform gates.','火车到站时，工作人员已经检查完所有车票并打开了站台闸门。','By the time the train arrived / the staff had checked every ticket / and opened the platform gates.','had + 过去分词构成过去完成时，表示另一过去事件之前已完成。','检票先于火车到站，展示完成时辅助动词用法。')],M('They have finished the inspection yesterday before the visitors arrived.','They finished the inspection yesterday before the visitors arrived.','明确的 yesterday 过去时间通常配一般过去时，不配现在完成时。','grammar'),[Q('have',1,1,'In “They have a small orchard,” have means?','own or possess','eat quickly','travel toward a place','此处 have 表示拥有。'),Q('have',2,2,'In “We had soup for lunch,” had means?','ate or drank','owned the restaurant','made the soup disappear magically','have 可表示吃喝、享用。'),Q('have',3,3,'In “They had a picnic by the lake,” had means?','did or took part in an activity','owned the lake permanently','made the picnic disappear','have 可表示进行或参加活动。'),Q('have',4,6,'In “You have to wear a helmet,” have to expresses?','necessity or obligation','a completed past action','ownership of a helmet factory','have to 表示必须、不得不。')]);
P('have fun','Have fun 是由 have 与 fun 构成的固定表达，意为玩得开心、享受活动；常用于祝愿或描述体验。',C('have fun.s1','社交与休闲','The children had fun building a blanket fort, even though it collapsed twice before dinner.','孩子们搭毯子堡玩得很开心，尽管晚饭前它塌了两次。','The children had fun building a blanket fort / even though it collapsed twice / before dinner.','have fun 后接动名词 building，说明享受的活动。','活动过程和意外都没影响孩子们玩得开心。'),M('We had fun at the picnic because everyone was bored and wanted to leave immediately.','We had fun at the picnic because we played games and laughed together.','所有人都无聊并急着离开，不符合玩得开心。'),[Q('have fun',1,1,'If guests have fun, they?','enjoy themselves','complete a tax form','feel required to leave','have fun 表示玩得开心。'),Q('have fun',2,1,'Which activity might make children have fun?','building a fort and inventing a game','waiting silently through a canceled party','being told to stop every activity','一起搭堡玩游戏符合愉快体验。'),Q('have fun',3,1,'“Have fun at the concert!” is usually?','a friendly wish that someone enjoys it','a warning not to enter the venue','a request to sell concert tickets','该句常用于祝人玩得开心。'),Q('have fun',4,1,'Choose the natural expression.','We had fun exploring the old harbor.','We fun had exploring the old harbor.','We had a fun while exploring the old harbor.','have fun 后可接动名词活动。')]);
P('have on','Have on 是短语动词，表示穿着某件衣物；口语中也可表示捉弄或欺骗某人，需由上下文区分。',C('have on.s1','衣着描述','At the station, Omar had on a bright orange raincoat that was easy to spot through the crowd.','在车站，奥马尔穿着一件亮橙色雨衣，隔着人群也很容易认出来。','At the station / Omar had on a bright orange raincoat / that was easy to spot through the crowd.','have on 后接所穿衣物；that 从句描述雨衣醒目。','雨衣作为穿在身上的衣物，体现穿着义。'),M('She had on her raincoat by carrying it folded inside her backpack.','She had on her raincoat by wearing it over her clothes.','把雨衣折好放在背包里不表示穿着。'),[Q('have on',1,1,'If someone has on a wool coat, the person is?','wearing the coat','selling the coat at a shop','washing the coat by hand','have on 表示穿着。'),Q('have on',2,1,'Which sentence describes clothing?','Mina had on silver gloves at the ceremony.','Mina had the joke on the table.','Mina had on a concert for Friday.','have on 后接衣物名词。'),Q('have on',3,1,'In casual speech, “Are you having me on?” can mean?','Are you joking with or deceiving me?','Are you lending me your jacket?','Are you asking me to host dinner?','另一口语义是捉弄或欺骗。'),Q('have on',4,1,'Why is context important with have on?','it can mean wearing something or joking with someone','it always names a kind of hat','it only describes weather','穿着义和捉弄义需看上下文。')]);
P('have to','Have to 是由 have 与不定式构成的情态表达，表示必须、不得不做某事；过去时常用 had to。',C('have to.s1','日常义务','Visitors have to show identification at the gate before they can enter the research building.','访客必须在进入研究楼前于门口出示身份证件。','Visitors have to show identification at the gate / before they can enter / the research building.','have to 后接动词原形 show；before 从句说明先决条件。','进入受控区域有明确要求，体现义务。'),M('Every visitor has to shows identification before entering the building.','Every visitor has to show identification before entering the building.','have to 后接动词原形，不能使用 shows。','grammar'),[Q('have to',1,1,'If you have to leave early, you?','are required or obliged to leave early','may never leave the building','have already left yesterday','have to 表示必须或不得不。'),Q('have to',2,1,'Which sentence expresses an external rule?','Employees have to wear badges inside the lab.','Employees enjoy wearing bright colors.','Employees had lunch in the lab.','实验室规定属于义务。'),Q('have to',3,1,'After “have to,” which form is standard?','the base form of a verb','a verb ending in -s in every case','only a past participle','have to 后接动词原形。'),Q('have to',4,1,'“We had to cancel” means?','cancellation was necessary','we might cancel but chose not to','the cancellation is happening tomorrow','had to 表示过去不得不做某事。')]);
P('haven','Haven 源自古英语 hæfen，与日耳曼语系中表示港口的词有关；现代指安全庇护处，也可指避风港或救助场所。',C('haven.s2','航海与天气','The fishing fleet waited in the haven until the storm passed and the harbor master reopened the channel.','暴风雨过去、港务长重新开放航道前，渔船队一直在避风港内等候。','The fishing fleet waited in the haven / until the storm passed / and the harbor master reopened the channel.','haven 作名词指可躲避风暴的港湾；until 引出等待的终点。','船只在受保护的港湾中躲避风暴，体现港口义。'),M('The sailors called the exposed reef a haven because it offered no shelter from the waves.','The sailors called the sheltered harbor a haven because it protected them from the waves.','暴露且无法挡浪的礁石不是安全庇护处。'),[Q('haven',1,1,'A haven for refugees is a place that offers?','safety and shelter','a dangerous crossing with no protection','a courtroom for routine tax cases','haven 的核心义是避难、安全处。'),Q('haven',2,2,'A sheltered haven for boats protects them from?','wind and rough seas','library fines','summer sunlight only','港湾可供船只避风。'),Q('haven',3,3,'A community garden can be described as a haven if it?','offers people a peaceful refuge','forces everyone to leave immediately','contains no plants or resting space','宁静且可休憩之地可比喻 haven。'),Q('haven',4,1,'Which place is most clearly a haven?','a safe shelter where displaced families can rest','an unguarded cliff in a storm','a road closed to all travelers','安全庇护所符合 haven。')]);
P('having','Having 是 have 的 -ing 形式，可作动名词或现在分词，表示拥有、持有；它也出现在 having done 等结构中表示先行完成。',C('having.s1','正式登记','Having a current permit is required before residents can reserve the shared workshop.','居民预约共享工坊前必须持有有效许可证。','Having a current permit / is required / before residents can reserve the shared workshop.','句首 having 短语作动名词主语，表示持有许可证这件事。','持有许可证是预约的先决条件。'),M('Having a current permit are required before residents can reserve the workshop.','Having a current permit is required before residents can reserve the workshop.','having 短语作单数概念的主语，谓语应用 is。','grammar'),[Q('having',1,1,'In “Having a key is useful,” having means?','possessing or holding','eating a meal','traveling home','having 是 have 的 -ing 形式，表示拥有。'),Q('having',2,1,'Which phrase uses having as a gerund subject?','Having enough time makes the trip easier.','They had lunch at noon.','The door has two locks.','句首 having 短语作主语。'),Q('having',3,1,'“Having finished the test, she left” means she left?','after she had finished the test','before she began the test','while she was starting the test','having finished 表示先完成再离开。'),Q('having',4,1,'Which form follows having in a perfect participle phrase?','a past participle, as in having checked','a bare noun only','the infinitive without to in every case','完成分词结构使用 having + 过去分词。')]);
P('havoc','Havoc 经古法语词形进入英语，其更早来源仍不确定；现代指大范围破坏，也可指严重混乱，常见搭配是 wreak havoc。',C('havoc.s2','秩序与混乱','A brief power failure wreaked havoc with the airport’s check-in system, leaving long queues at every desk.','短暂停电给机场值机系统造成严重混乱，每个柜台前都排起了长队。','A brief power failure wreaked havoc with the airport’s check-in system / leaving long queues / at every desk.','wreak havoc with 是固定搭配，表示严重扰乱；leaving 引出后果。','系统故障引发全机场排队，体现混乱义。'),M('The orderly rollout wreaked havoc because every system worked perfectly and no one waited.','The outage wreaked havoc because the check-in system failed and queues spread.','系统正常、无人等待不构成破坏或混乱。'),[Q('havoc',1,1,'A storm that wreaks havoc causes?','widespread damage or disorder','a small improvement in the weather','a quiet afternoon with no effects','havoc 表示严重破坏或混乱。'),Q('havoc',2,2,'Which phrase is standard?','wreak havoc on the schedule','manufacture havoc from the schedule','wear havoc on the schedule','常用搭配为 wreak havoc。'),Q('havoc',3,1,'If a computer bug causes havoc, it?','seriously disrupts normal operation','organizes every file flawlessly','adds a pleasant decoration','bug 严重扰乱运行会造成 havoc。'),Q('havoc',4,2,'A city may be left in havoc after?','a disaster damages roads and interrupts services','a meeting ends early with no changes','a library adds several new books','灾害破坏交通和服务会造成混乱。')]);
P('hawk','Hawk 源自古英语 hafoc，名词指捕食性猛禽，也可指主张强硬政策的人；动词还表示沿街叫卖或清嗓般咳出。',C('hawk.s3','街头贸易','Vendors hawked roasted chestnuts along the station entrance, calling out to commuters in the evening rush.','小贩在车站入口沿街兜售烤栗子，傍晚高峰时向通勤者吆喝。','Vendors hawked roasted chestnuts / along the station entrance / calling out to commuters in the evening rush.','hawk 作动词表示叫卖；calling out 补充叫卖方式。','小贩吆喝着售卖商品，符合街头兜售义。'),M('The vendors hawked chestnuts by hiding them and refusing to offer any for sale.','The vendors hawked chestnuts by calling out their price to passersby.','隐藏货物且不出售与叫卖行为相反。'),[Q('hawk',1,1,'A hawk circling above a field is a?','bird of prey hunting small animals','farm tool for breaking soil','small fish raised in a hatchery','hawk 的常见名词义是猛禽。'),Q('hawk',2,2,'A political hawk generally favors?','a forceful or aggressive policy','complete opposition to all action','only artistic changes to a flag','政治 hawk 指主张强硬行动的人。'),Q('hawk',3,3,'Street vendors hawk their goods when they?','call out to sell them','hide them from customers','give them away without offering them','hawk 表示沿街叫卖。'),Q('hawk',4,4,'To hawk phlegm means to?','clear the throat noisily to bring it up','sell a product at a market','train a bird to hunt','动词另有用力清嗓、咳出之义。')]);
P('hawker','Hawker 由 hawk 加施事后缀 -er 构成，指在街上或公共场所兜售商品的小贩。',C('hawker.s1','街市交易','A fruit hawker pushed a handcart through the lane, calling out the price of ripe mangoes.','一名水果小贩推着手推车穿过小巷，吆喝着报出熟芒果的价格。','A fruit hawker pushed a handcart through the lane / calling out the price / of ripe mangoes.','hawker 指叫卖商品的人；calling out 补充其销售方式。','推车并向路人叫卖水果，符合小贩义。'),M('The hawker sold no goods and stayed in a locked office away from customers.','The hawker sold fruit to passersby from a cart in the lane.','不卖货且远离顾客不符合 hawker 的职业含义。'),[Q('hawker',1,1,'A street hawker earns money by?','selling goods to people in public places','repairing aircraft engines in a hangar','teaching children to swim','hawker 指沿街售货的小贩。'),Q('hawker',2,1,'Which person is a hawker?','a vendor calling out the price of fruit','a passenger reading a ticket','a farmer storing empty baskets','沿街叫卖水果者是 hawker。'),Q('hawker',3,1,'The suffix -er in hawker identifies?','a person who performs an activity','a place where eggs hatch','a quality of being harsh','-er 可构成表示从事者的名词。'),Q('hawker',4,1,'A hawker is most likely to approach?','passersby in a market lane','pilots inside a locked cockpit','fish deep below the sea','小贩通常面向街上市民售货。')]);
P('hawthorn','Hawthorn 由 haw（山楂果）与 thorn（刺、带刺植物）组合而成，指蔷薇科的山楂灌木或小乔木。',C('hawthorn.s1','园艺与植物','In late spring, the hawthorn hedge filled with white blossoms, and red haws appeared by autumn.','晚春时山楂树篱开满白花，到了秋天则结出红色山楂果。','In late spring / the hawthorn hedge filled with white blossoms / and red haws appeared by autumn.','hawthorn 是植物名；and 连接花期与结果的季节变化。','白花、红果和树篱特征对应山楂。'),M('The gardener called the thornless orange tree a hawthorn even though it produced no haws.','The gardener called the thorny hedge plant a hawthorn after identifying its blossoms and red haws.','没有刺也不结山楂果的橙树与山楂特征不符。'),[Q('hawthorn',1,1,'A hawthorn is a?','thorny shrub or small tree with blossoms and haws','large tropical palm with coconuts','flowering grass used as wheat','hawthorn 是带刺的山楂灌木或小树。'),Q('hawthorn',2,1,'Which feature may identify a hawthorn hedge?','white or pink flowers followed by red haws','blue cones growing under the soil','feathers covering its branches','山楂常开白或粉花并结红果。'),Q('hawthorn',3,1,'The word hawthorn names a kind of?','plant in the rose family','metal tool used by a blacksmith','bird of prey','山楂属于蔷薇科植物。'),Q('hawthorn',4,1,'A gardener plants hawthorn mainly to grow?','a hedging shrub that can bear haws','a cereal crop for flour','a climbing vine with no woody stem','山楂常作带刺树篱。')]);
P('hay','Hay 源自古英语 hieg 一类表示割下的草的词，指晒干作饲料的草；在少数俚语表达中也可指钱。',C('hay.s1','畜牧与饲料','The ranch stored dry hay in the loft so the horses would have feed during the snowy months.','牧场把干草存进阁楼，好让马匹在多雪的月份有饲料。','The ranch stored dry hay in the loft / so the horses would have feed / during the snowy months.','hay 是干草不可数名词；so 引出储存目的。','干草留作冬季牲畜饲料，符合核心义。'),M('The ranch fed the horses fresh hay that had never been cut or dried.','The ranch fed the horses hay that had been cut and dried.','hay 是割下并晒干的草，不是未经收割的鲜草。'),[Q('hay',1,1,'Hay is grass that has been?','cut and dried, often for animal feed','frozen while still growing','ground into metal parts','hay 指割下晒干的草。'),Q('hay',2,2,'In the informal phrase “make hay,” hay can refer to?','money','a type of winter coat','a farm’s water supply','俚语表达中 hay 可指钱。'),Q('hay',3,1,'Which animal might be fed hay in winter?','a horse','a shark','a hawk kept in flight','干草常用来喂马等牲畜。'),Q('hay',4,1,'A farmer stores hay to?','provide dry fodder when fresh grass is scarce','plant it like a seed in a field','turn it into drinking water','储存干草可供冬季喂养牲畜。')]);
P('haystack','Haystack 由 hay 与 stack 组合，指堆放的干草堆；在 needle in a haystack 中比喻极难找到的东西。',C('haystack.s2','搜索与比喻','Finding one unsigned form in a warehouse of boxes felt like searching for a needle in a haystack.','要在满仓库的箱子里找出一张未签字的表格，简直像大海捞针。','Finding one unsigned form in a warehouse of boxes / felt like searching / for a needle in a haystack.','needle in a haystack 是固定比喻，表示在大量相似事物中很难找到目标。','一张表格藏在成堆箱子里，突出寻找难度。'),M('The missing paper was a needle in a haystack because it was the only sheet on an empty desk.','The missing paper was a needle in a haystack among thousands of similar files.','空桌上的唯一文件很容易找到，不构成大海捞针。'),[Q('haystack',1,1,'A haystack is literally a?','large pile of stored dry grass','stack of sharpened needles','small pool for watering crops','haystack 的字面义是干草堆。'),Q('haystack',2,2,'A needle in a haystack describes something?','very difficult to find among many similar things','lying alone in a clear, empty room','too large to fit inside a barn','习语表示目标难以从大量事物中找出。'),Q('haystack',3,1,'Where might a farmer build a haystack?','near a barn to store dry fodder','underwater beside a coral reef','inside a kitchen oven','干草堆用于储存牲畜饲料。'),Q('haystack',4,2,'Why is the idiom “needle in a haystack” effective?','it contrasts one tiny target with a huge pile','it describes a needle made of grass','it names a tool for harvesting grain','少量目标藏在庞大堆中，凸显难找。')]);
P('hazard','Hazard 经古法语 hasard 进入英语，更早来源有争议；名词指危险或障碍，动词可表示使冒险或冒险提出。',C('hazard.s3','意见表达','At the review, the junior analyst hazarded a guess about the missing shipment, making clear that she had no proof.','评审会上，初级分析师冒险猜测了失踪货物的去向，并明确说明自己没有证据。','At the review / the junior analyst hazarded a guess / about the missing shipment / making clear that she had no proof.','hazard a guess 是冒险提出猜测；making clear 补充其谨慎说明。','没有证据仍试探性发言，体现“冒险提出”义。'),M('She hazarded a guess with complete certainty and claimed it was proven fact.','She hazarded a guess while admitting she lacked evidence.','hazard a guess 表示带风险的试探，不应宣称毫无疑问地已证实。'),[Q('hazard',1,1,'A chemical hazard is something that?','may cause harm or damage','guarantees perfect safety','is used only to decorate a room','hazard 名词指潜在危险。'),Q('hazard',2,2,'On a golf course, a hazard is?','an obstacle or difficult area','the club used to strike the ball','the player’s scorecard','高尔夫中 hazard 指障碍区。'),Q('hazard',3,3,'To hazard an opinion is to?','offer it despite some risk or uncertainty','hide it until everyone agrees','prove it with a laboratory test','动词可表示冒险提出意见。'),Q('hazard',4,4,'If a driver hazards a guess, the driver?','ventures a guess without full certainty','records a confirmed measurement','refuses to speak under any condition','动词还可表示冒险猜测。')]);
P('hazardous','Hazardous 由 hazard 加形容词后缀 -ous 构成，表示有危险或有害；也可指依赖运气、安排冒险的做法。',C('hazardous.s1','工作安全','Workers wore sealed gloves because the solvent was hazardous if absorbed through the skin.','由于这种溶剂若经皮肤吸收会有危险，工人都戴上了密封手套。','Workers wore sealed gloves / because the solvent was hazardous / if absorbed through the skin.','hazardous 作表语形容词；because 从句说明防护原因。','皮肤吸收会造成伤害，明确体现危险性。'),M('The label described the harmless drinking water as hazardous even though tests showed no risk.','The label described the toxic solvent as hazardous because it could damage health.','检测无害的饮水不应标记为有危险。'),[Q('hazardous',1,1,'A hazardous material is one that?','can cause harm to people or the environment','is guaranteed harmless in every amount','is used only for decoration','hazardous 表示可能造成伤害。'),Q('hazardous',2,2,'A hazardous journey depending on luck is?','risky and uncertain','carefully planned and safe','already completed without any risk','hazardous 也可形容冒险、不稳妥。'),Q('hazardous',3,1,'Which item needs a hazardous-material warning?','a corrosive liquid that can burn skin','a sealed bag of clean cotton','a book with a torn cover','腐蚀性液体会伤害皮肤。'),Q('hazardous',4,2,'Hazardous is formed from hazard plus a suffix meaning?','having the quality or nature of','the person who performs an action','the place where something is stored','-ous 常构成表示“具有……性质”的形容词。')]);
P('haze','Haze 的词源仍不确定；名词可指空气中的薄雾、烟尘或思维记忆的模糊，动词可指使视线模糊，也可指欺凌新生。',C('haze.s4','校园与新人','The older students were disciplined for hazing first-years by forcing them to perform humiliating tasks.','高年级学生因强迫新生做羞辱性任务而受到处分。','The older students were disciplined / for hazing first-years / by forcing them to perform humiliating tasks.','haze 作动词可指欺凌新生；by 引出具体手段。','强迫新生做羞辱任务是 hazing 的欺凌行为。'),M('The seniors hazed the newcomers by welcoming them kindly and letting them opt out of every activity.','The seniors hazed the newcomers by forcing them into degrading initiation tasks.','友善欢迎并允许退出并非欺凌。'),[Q('haze',1,1,'A haze over a valley is usually?','a thin cloud of mist, smoke, or dust','a solid wall of ice','a loud musical performance','haze 名词可指空气中的薄雾或烟尘。'),Q('haze',2,2,'A mental haze makes it hard to?','think clearly or remember precisely','see a bright color more sharply','hear a loud alarm','比喻义是思维记忆模糊。'),Q('haze',3,3,'Smoke can haze a window by?','making the view through it unclear','repairing the glass automatically','turning the window into a door','动词可指使视线朦胧。'),Q('haze',4,4,'To haze new students is to?','bully them with humiliating initiation demands','help them find their classrooms','teach them how to study safely','校园义指欺凌新生。')]);
P('hazel','Hazel 源自古英语 haesel，作名词指榛树或榛子，作形容词则指带绿或金色调的淡褐色，尤常形容眼睛。',C('hazel.s2','外貌描述','In the afternoon light, her hazel eyes looked green near the window and golden beside the lamp.','在午后光线下，她的淡褐色眼睛靠窗时显绿，靠近台灯时又显出金色。','In the afternoon light / her hazel eyes looked green near the window / and golden beside the lamp.','hazel 修饰 eyes，表示带绿或金色调的淡褐色；光线改变颜色观感。','随光线呈现棕绿或金调是 hazel eyes 的常见特征。'),M('The botanist described a blue-eyed subject’s eyes as hazel while noting they were uniformly bright blue.','The botanist described the subject’s brown-green eyes as hazel.','纯蓝眼睛不符合 hazel 的淡褐、棕绿色调。'),[Q('hazel',1,1,'A hazel is a?','shrub or small tree that bears edible nuts','large sea bird with hooked wings','grain crop ground into flour','hazel 名词指榛树或榛子。'),Q('hazel',2,2,'Hazel eyes are often?','light brown with green or golden tones','uniformly black with no brown','bright violet in every light','hazel 形容眼睛多指淡褐并带绿或金调。'),Q('hazel',3,1,'Which item could grow on a hazel?','edible nuts called hazelnuts','pineapples on a tropical stem','rice grains under water','榛树结可食用榛子。'),Q('hazel',4,2,'In “a hazel-eyed child,” hazel describes the child’s?','eye color','height','hearing ability','此处 hazel 描述眼睛颜色。')]);
P('hazy','Hazy 由 haze 加形容词后缀 -y 构成，形容被薄雾遮住而不清晰，也可形容记忆或计划模糊不明。',C('hazy.s1','天气与能见度','The distant lighthouse looked hazy through the sea mist, so the crew slowed the boat before entering the channel.','隔着海雾，远处的灯塔显得朦胧，因此船员在进入航道前减慢了船速。','The distant lighthouse looked hazy through the sea mist / so the crew slowed the boat / before entering the channel.','hazy 作表语形容词，描述灯塔不清晰；so 引出谨慎应对。','海雾使灯塔看不清，符合字面义。'),M('The mountain remained hazy because every detail was sharply visible through the clear air.','The mountain looked hazy because mist blurred its outline.','细节清楚且空气通透与朦胧模糊相反。'),[Q('hazy',1,1,'A hazy view is?','unclear, as if covered by mist','perfectly sharp at every distance','completely silent','hazy 表示模糊、朦胧。'),Q('hazy',2,1,'A hazy memory of childhood is?','not clear in the mind','remembered in exact detail','written in a signed contract','比喻义指记忆不清楚。'),Q('hazy',3,1,'Which weather might make a skyline hazy?','mist or smoke in the air','crystal-clear dry air','a quiet room with curtains closed','空气中的雾或烟会使景物模糊。'),Q('hazy',4,1,'A hazy plan needs?','more precise details','less information and more confusion','a stronger fog machine','模糊计划需要补充明确细节。')]);
P('he','He 源自古英语 hē，常作男性单数代词；旧式英语还曾用 he 泛指性别不明的人，现代通常改用 they 等中性表达。',C('he.s2','语言使用史','Older manuals sometimes wrote “Every student should bring his book,” using he generically; current guides often choose singular they.','较早的手册有时写“Every student should bring his book”，用 he 泛指；现代指南常改用单数 they。','Older manuals sometimes wrote the example / using he generically / current guides often choose singular they.','generic he 是历史上的泛指用法；现代编辑常选中性代词。','例句明确标出旧式泛指习惯及其现代替代。'),M('When the guide addresses a woman named Leah, it uses he as the agreed personal pronoun.','When the guide addresses Leah, it uses she, her stated pronoun.','已知 Leah 使用 she 时，擅自改用 he 不符合其代词指代。','usage'),[Q('he',1,1,'In “He left his coat,” he refers to?','a male person or animal already mentioned','a location that has no person','a plural group in every context','he 常指已提及的男性或雄性动物。'),Q('he',2,2,'Older generic he was used to refer to?','a person of unspecified sex in older usage','only a group of women','a machine with no human reference','旧式英语曾用 he 泛指任何性别的人。'),Q('he',3,1,'In contemporary inclusive writing, a common alternative to generic he is?','singular they','the word “there”','a plural noun with no pronoun','现代常用单数 they 作中性表达。'),Q('he',4,1,'If someone’s stated pronoun is he, respectful reference uses?','he and him for that person','she only, regardless of their request','no pronouns in every sentence','尊重当事人使用的代词。')]);
P('head','Head 源自古英语 heafod，名词可指身体头部、头脑、负责人或顶端；作动词还可指朝向某处或领导队伍。',[C('head.s5','旅行与方向','After the ranger checked the weather, the hikers headed north toward the sheltered valley.','护林员查看天气后，徒步者朝北前往有遮蔽的山谷。','After the ranger checked the weather / the hikers headed north / toward the sheltered valley.','head 作动词可表示朝某方向前进；north 是方向副词。','队伍向北移动，体现动词义。'),C('head.s4','物体位置','A small brass ornament sat at the head of the staircase, marking the point where the rail turned.','楼梯顶端放着一件小铜饰，标示栏杆转弯的位置。','A small brass ornament sat at the head of the staircase / marking the point / where the rail turned.','at the head of 表示顶部或前端；where 从句说明位置特征。','装饰位于楼梯的顶端，体现位置义。')],M('The committee chose a head for the department, meaning they selected a new ceiling above the office.','The committee chose a head for the department, meaning they selected the person in charge.','部门的 head 指负责人，不是办公室天花板。'),[Q('head',1,1,'The head of a person is the part?','above the neck that contains the brain','between the knee and ankle','inside the chest that pumps blood','身体部位义是脖子以上的头部。'),Q('head',2,2,'A quick head for figures suggests someone has?','mental ability with numbers','a large hat collection','a job repairing roofs','head 可比喻头脑、才智。'),Q('head',3,3,'The head of a school is the person?','in charge of the school','who cleans every desk','who sells textbooks outside','head 可指负责人或校长。'),Q('head',4,5,'When hikers head east, they?','travel in an easterly direction','lead the east side of a meeting only','measure the height of a hill','head 作动词表示朝某方向前往。')]);
P('head of state','Head of state 由 head 与 state 组成，指代表国家并担任最高国家元首职务的人；具体权力因政体而异。',C('head of state.s1','政府与外交','The head of state welcomed the visiting delegation at the palace before the treaty ceremony began.','条约仪式开始前，国家元首在宫殿迎接了来访代表团。','The head of state welcomed the visiting delegation / at the palace / before the treaty ceremony began.','head of state 是名词短语；welcome 的宾语是代表团。','代表国家进行正式外交接待是国家元首职责场景。'),M('The head of state was defined as the country’s leading weather reporter with no public office.','The head of state was defined as the country’s highest representative officeholder.','天气记者并非国家元首职务。'),[Q('head of state',1,1,'A head of state is the?','highest official representative of a country','manager of a private grocery store','captain of every ship in a harbor','head of state 指国家最高元首或代表。'),Q('head of state',2,1,'Which duty might a head of state perform?','welcoming a foreign delegation in an official ceremony','repairing every road personally','writing every school textbook','正式接待外国代表团符合职责。'),Q('head of state',3,1,'Do all heads of state have identical political powers?','No; powers depend on the country’s political system.','Yes; every one has exactly the same authority.','No; the title always means a monarch only.','不同政体下元首权力不同。'),Q('head of state',4,1,'The phrase head of state refers to a role at the level of?','a nation','a single household kitchen','a neighborhood sports club','该职位属于国家层级。')]);
P('head office','Head office 是固定名词短语，指公司或机构的总部、主要办公地点，常与分支机构相对。',C('head office.s1','公司组织','The regional branches sent their sales figures to the head office, where the finance team prepared the annual report.','各地区分部把销售数据送到总部，财务团队在那里编制年度报告。','The regional branches sent their sales figures to the head office / where the finance team prepared / the annual report.','head office 指总部；where 从句补充总部开展的工作。','分支机构向主要办公室汇报，体现总部义。'),M('The company’s head office was the smallest branch because all central decisions were made elsewhere.','The company’s head office was where central teams coordinated the branches.','所有决策都在别处且此处是最小分支，与总部的职能相反。'),[Q('head office',1,1,'A company’s head office is its?','main administrative office','smallest retail counter','temporary customer queue','head office 指公司总部。'),Q('head office',2,1,'A branch usually reports to the?','head office','company’s loading dock','nearest bus stop','分支机构常向总部汇报。'),Q('head office',3,1,'Which task is likely handled at a head office?','coordinating decisions across several branches','serving one table in a café','repairing a customer’s bicycle at home','总部常负责跨分支协调。'),Q('head office',4,1,'Head office is closest in meaning to?','headquarters','checkout line','warehouse entrance','head office 与 headquarters 意思相近。')]);
P('head teacher','Head teacher 是 head 与 teacher 构成的英式英语职务名称，指学校的负责人，即校长。',C('head teacher.s1','校园管理','The head teacher met parents in the assembly hall to explain the school’s new attendance policy.','校长在礼堂会见家长，说明学校新的出勤政策。','The head teacher met parents in the assembly hall / to explain / the school’s new attendance policy.','head teacher 是复合名词，指学校负责人；to explain 表示会面的目的。','代表学校说明政策的是校长职责。'),M('The head teacher was the newest pupil because the phrase means a student at the front of class.','The head teacher was the person responsible for leading the school.','head teacher 指学校负责人，不是排在前面的学生。'),[Q('head teacher',1,1,'A school’s head teacher is the?','person in charge of the school','student who arrives first each morning','teacher who teaches only anatomy','head teacher 指校长。'),Q('head teacher',2,1,'Who would announce a whole-school attendance policy?','the head teacher','a visiting bus passenger','a student’s younger sibling','全校政策通常由校长说明。'),Q('head teacher',3,1,'Head teacher is a common title in?','British English','only American baseball','computer programming syntax','该职务称呼常见于英式英语。'),Q('head teacher',4,1,'The word head in head teacher indicates?','leadership responsibility','the lesson is about anatomy','the teacher’s physical height','head 在此表示负责人身份。')]);
P('headache','Headache 由 head 与 ache 组合，指头部疼痛；也可比喻令人烦恼或难以处理的问题。',C('headache.s2','问题处理','Coordinating deliveries from six suppliers became a headache when each truck arrived at a different gate.','六家供应商的卡车各从不同大门抵达，协调送货成了一件令人头疼的事。','Coordinating deliveries from six suppliers / became a headache / when each truck arrived at a different gate.','become a headache 是比喻表达，指变成棘手烦恼的问题。','多方送货难以协调，体现问题义。'),M('The delivery schedule was a headache because every truck arrived exactly as planned and caused no work.','The delivery schedule became a headache when trucks arrived at conflicting times.','按计划准时且毫无额外工作不构成麻烦。'),[Q('headache',1,1,'A headache is usually?','pain in the head','pain limited to the ankle','a type of school principal','头痛是头部疼痛。'),Q('headache',2,2,'A paperwork headache is?','an annoying problem that is difficult to manage','a medical diagnosis of a broken arm','a pleasant surprise at work','比喻义指烦人的难题。'),Q('headache',3,1,'Which might cause a headache for an event planner?','three venues changing their schedules at once','one venue confirming the time clearly','guests arriving at the announced hour','多处时间同时变动会造成协调麻烦。'),Q('headache',4,2,'“The delay gave us a headache” means the delay?','created a troublesome problem','caused everyone’s hair to grow','cured a physical illness','这里 headache 指令人烦恼的问题。')]);
P('headbutt','Headbutt 是 head 与 butt 的复合词，指用头撞击的动作，也可作动词表示以头冲撞。',C('headbutt.s1','体育安全','During the match, the referee stopped play after a player’s headbutt struck an opponent in the chest.','比赛中，一名球员用头撞到对手胸口后，裁判立即停止了比赛。','During the match / the referee stopped play / after a player’s headbutt struck an opponent in the chest.','headbutt 作名词指头撞动作；after 从句交代裁判停赛原因。','以头撞击对手是违规或危险动作。'),M('The player headbutted his opponent by tapping the ball gently with his foot.','The player kicked the ball with his foot and avoided headbutting his opponent.','用脚踢球不是用头撞人。'),[Q('headbutt',1,1,'A headbutt is a blow delivered with the?','head','heel of the shoe','handle of a tool','headbutt 指用头撞击。'),Q('headbutt',2,1,'If one player headbutts another, the player?','strikes the other with the head','throws the ball over the fence','shakes hands after the match','动词表示以头冲撞。'),Q('headbutt',3,1,'Why would a referee stop a match after a headbutt?','it is a dangerous physical strike','it is a legal way to score in every sport','it means the match has ended normally','头撞可能伤人，裁判会制止。'),Q('headbutt',4,1,'Headbutt is formed from which two ideas?','head and a butt or strike','head and a musical instrument','hat and a narrow boat','复合词包含头和撞击的意思。')]);
P('header','Header 由 head 加名词后缀 -er 构成，可指页面或文件顶部的标题信息；在足球中也指用头顶球的动作或球。',C('header.s1','网页与文件','The report template places the department name in the header so it appears at the top of every printed page.','报告模板把部门名称放在页眉里，使它出现在每张打印页的顶部。','The report template places the department name in the header / so it appears / at the top of every printed page.','header 指页首信息；so 从句说明放入页眉后的效果。','固定出现在每页顶部的文字是页眉。'),M('The document’s header appeared only at the bottom of every page beneath the footnotes.','The document’s header appeared at the top of each page above the text.','页底脚注下方是页脚位置，不是 header。'),[Q('header',1,1,'A document header appears?','at the top of a page or file','only in the middle of a paragraph','under the floor of a building','header 可指页面顶部信息。'),Q('header',2,1,'Which item belongs in a page header?','a running title repeated above the page text','a final footnote below the last line','a note hidden in the binding','重复置于正文上方的标题可放在页眉。'),Q('header',3,1,'In football, a header is made by?','striking the ball with the head','kicking it with the heel','throwing it in from the sideline','体育义指头球。'),Q('header',4,1,'The page header is opposite in position to the?','footer at the bottom of the page','book cover on the outside','spine along the binding','header 在页顶，footer 在页底。')]);
P('heading','Heading 来自 head 加 -ing，可指文章或页面标题、页眉，也可指船只或移动物的方向。',C('heading.s3','航行与方位','The ferry’s heading shifted slightly west when the captain steered around the shallow reef.','船长绕过浅礁时，渡轮的航向略微转向西边。','The ferry’s heading shifted slightly west / when the captain steered / around the shallow reef.','heading 作名词表示航向；when 从句解释方向改变的原因。','船只朝向西边改变，体现航行方向义。'),M('The vessel’s heading was its printed title in the newspaper above the weather report.','The vessel’s heading was its direction of travel across the water.','船只的 heading 在航行语境中指方向，不是报纸标题。'),[Q('heading',1,1,'A heading above an article is its?','title or label','last sentence in the article','author’s private address','heading 可指文章标题。'),Q('heading',2,2,'A page heading repeated at the top is similar to a?','header','harvest','hatchway','页面顶部的 heading 可指页眉。'),Q('heading',3,3,'A ship’s heading tells you?','the direction in which it is moving','the number of passengers aboard','the age of the ship’s engine','航海 heading 表示航向。'),Q('heading',4,1,'Which sentence uses heading as a title?','The heading “Safety Rules” begins the next section.','The ship changed heading to avoid rocks.','Her heading was due north at sea.','“Safety Rules”是文章分节标题。')]);
P('headland','Headland 由 head 与 land 组合，指伸入海中的高地或岬角，通常形成海岸线向外突出的部分。',C('headland.s1','海岸地貌','The lighthouse stands on a rocky headland that projects into the bay and catches strong ocean winds.','灯塔立在一处伸入海湾的岩石岬角上，那里常遭强劲海风。','The lighthouse stands on a rocky headland / that projects into the bay / and catches strong ocean winds.','headland 是海岸突出地形；that 从句描述岬角伸入海湾。','陆地突出伸向海湾，符合海岬地貌。'),M('The map labeled the flat inland desert, far from any coast, as a headland.','The map labeled the rocky point extending into the sea as a headland.','远离海岸的内陆沙漠不是海岬。'),[Q('headland',1,1,'A headland is a piece of land that?','projects into the sea from the coast','lies deep underground beneath a city','floats offshore without any connection to land','headland 指向海中突出的海岸高地。'),Q('headland',2,1,'A lighthouse may be built on a headland because it?','extends into the water and overlooks the coast','is always the lowest point inland','moves with the tide','岬角伸入海中，适合观察海岸。'),Q('headland',3,1,'Which feature is a headland?','a rocky coastal point jutting into a bay','a river flowing through a plain','a hill hundreds of miles from shore','伸入海湾的岩石海岸突出部是岬角。'),Q('headland',4,1,'Headland belongs to the geography of?','coasts and shorelines','deep space','underground plumbing','headland 是海岸地貌。')]);
P('headline','Headline 由 head 与 line 组合，指报刊文章的大标题或头条新闻；作动词可表示担任主打演出或给报道加标题。',C('headline.s3','新闻编辑','The editor headlined the report “Bridge Reopens After Six Months” to emphasize the public impact.','编辑把报道标题定为“桥梁历经六个月后重新开放”，以突出其对公众的影响。','The editor headlined the report / “Bridge Reopens After Six Months” / to emphasize the public impact.','headline 作动词表示为报道加标题；引号内是所用标题。','编辑把具体文字放在报道标题位置，符合动词义。'),M('The editor headlined the report by hiding its title and removing every line of text.','The editor headlined the report with a clear title above the story.','隐藏标题并删掉所有文字不是给报道加标题。'),[Q('headline',1,1,'A newspaper headline is the?','large title above an article','small correction hidden in an appendix','price printed on the back cover','headline 指报纸文章的大标题。'),Q('headline',2,2,'A headline story is an?','important news item receiving prominent coverage','unpublished note for the editor only','advertisement for a used vehicle','headline 也可指头条要闻。'),Q('headline',3,3,'A singer who headlines a festival?','is the main featured performer','sells tickets at the entrance','writes the weather forecast','动词 headline 可指担任主打演出。'),Q('headline',4,3,'If a newspaper headlines a story, it?','gives the story a prominent title','removes the story from the page','turns the story into a sound recording','动词也可表示给报道加标题。')]);
P('headmaster','Headmaster 由 head 与 master 组合，传统上指学校负责人；该词有性别色彩，女性校长对应词 headmistress。',C('headmaster.s1','学校管理','The headmaster addressed the pupils at assembly and reminded them that the library would close early on Friday.','校长在集会上向学生讲话，提醒他们图书馆周五会提前关闭。','The headmaster addressed the pupils at assembly / and reminded them / that the library would close early on Friday.','headmaster 指学校负责人；that 从句转述通知内容。','面向全校学生发布校务通知体现校长职责。'),M('The headmaster was the newest pupil because the title means a child who leads the line.','The headmaster was the person responsible for leading the school.','headmaster 指校长，不是排队领头的学生。'),[Q('headmaster',1,1,'A headmaster is traditionally the?','man in charge of a school','person who repairs the school roof','student with the tallest hat','headmaster 传统上指男性校长。'),Q('headmaster',2,2,'The traditional female counterpart of headmaster is?','headmistress','headland','headway','女性校长对应词为 headmistress。'),Q('headmaster',3,1,'Which responsibility fits a headmaster?','addressing pupils about a school-wide policy','selling train tickets at the station','leading a fishing fleet through a storm','校长可向学生说明校务政策。'),Q('headmaster',4,1,'The head in headmaster refers to?','leadership of the school','the anatomy lesson on Monday','a decorative roof ornament','head 表示学校负责人。')]);
P('headquarter','Headquarter 由 headquarters 反向形成动词，表示把组织总部设在某个地点，常用被动结构 be headquartered。',C('headquarter.s1','企业布局','The software company is headquartered in Dublin, although most of its engineers work remotely.','这家软件公司的总部设在都柏林，尽管多数工程师远程工作。','The software company is headquartered in Dublin / although most of its engineers / work remotely.','be headquartered in 后接总部所在地；although 引出对比情况。','都柏林是公司的总部地点，体现动词义。'),M('The firm headquartered in Dublin means its main office was moved out of Dublin and placed elsewhere.','The firm is headquartered in Dublin, where its main office is based.','be headquartered in 表示总部设在该处，而非迁离该处。','grammar'),[Q('headquarter',1,1,'A company headquartered in Nairobi?','has its main base or office there','has no office anywhere','sells only headwear in that city','headquarter 作动词表示将总部设于某处。'),Q('headquarter',2,1,'Which sentence uses headquarter as a verb?','The charity is headquartered in Accra.','The charity’s headquarter is blue.','They bought a headquarter yesterday.','be headquartered in 是常用被动表达。'),Q('headquarter',3,1,'To headquarter an organization in a city is to?','base its central office in that city','close every branch in that city','move the city’s government to another country','表示把组织总部设在某地。'),Q('headquarter',4,1,'Which preposition commonly follows headquartered?','in, as in “headquartered in Oslo”','under, as in “headquartered under Oslo”','onto, as in “headquartered onto Oslo”','总部所在地常由 in 引出。')]);
P('headquarters','Headquarters 由 head 与 quarter（驻扎或办公地点）构成，形式虽以 -s 结尾，通常指组织总部，也可指军事司令部。',C('headquarters.s2','军事指挥','The rescue operation’s headquarters was set up in a school gym, where coordinators tracked teams and supplies.','救援行动的指挥部设在一所学校的体育馆里，协调员在那里追踪各小队和物资。','The rescue operation’s headquarters was set up in a school gym / where coordinators tracked / teams and supplies.','headquarters 在此指行动指挥部；where 从句补充其用途。','协调救援小队和物资的地点承担指挥职能。'),M('The army’s headquarters was a single soldier walking alone without any command post or staff.','The army’s headquarters was the command post where officers coordinated the operation.','单独行走的士兵不是指挥部或司令部。'),[Q('headquarters',1,1,'A company’s headquarters is its?','main office or central base','smallest branch in a distant town','customer’s private home','headquarters 可指公司总部。'),Q('headquarters',2,2,'Military headquarters is where?','operations are commanded and coordinated','all weapons are manufactured by hand','soldiers go only to buy lunch','军事语境中指挥行动的地点是司令部。'),Q('headquarters',3,1,'Why does headquarters end in -s?','the plural-looking form is commonly used for one central office','it always means several unrelated buildings','the word can only be a verb','单个总部也常用复数形式 headquarters。'),Q('headquarters',4,2,'A nonprofit’s headquarters would usually contain?','central staff coordinating the organization','only a temporary visitor’s coat','a field of crops ready for harvest','总部承担机构中心协调工作。')]);
P('headstrong','Headstrong 由 head 与 strong 组合，形容固执倔强、不愿听从建议或改变决定的人。',C('headstrong.s1','性格与协商','Although the headstrong captain ignored several warnings, the crew persuaded him to wait for the fog to lift.','尽管固执的船长无视了几次警告，船员还是说服他等雾散去。','Although the headstrong captain ignored several warnings / the crew persuaded him / to wait for the fog to lift.','headstrong 修饰 captain；although 引出与劝说结果相反的行为。','无视劝告体现固执，后来才同意等待。'),M('The headstrong captain immediately changed course whenever anyone offered advice.','The headstrong captain refused to change course despite repeated advice.','轻易接受建议并改变主意与固执倔强相反。'),[Q('headstrong',1,1,'A headstrong person is likely to?','insist on their own choice despite advice','change their view whenever asked','avoid making any decision','headstrong 指固执、不听劝。'),Q('headstrong',2,1,'Which character seems headstrong?','a driver who ignores warnings and refuses to slow down','a patient listener who considers every suggestion','a clerk who follows a clear safety rule','无视警告并拒绝调整体现倔强。'),Q('headstrong',3,1,'Headstrong usually describes someone’s?','stubborn temperament','physical height','ability to hear music','headstrong 描写性格。'),Q('headstrong',4,1,'Which is closest to headstrong?','stubborn','flexible','indifferent','近义词为 stubborn。')]);
P('headway','Headway 由 head 与 way 组合，原指向前行进的空间，现代常用于 make headway，表示取得进展。',C('headway.s1','项目进度','The research team made headway after replacing the faulty sensor and collecting a week of reliable readings.','研究团队更换故障传感器并收集一周可靠读数后，取得了进展。','The research team made headway / after replacing the faulty sensor / and collecting a week of reliable readings.','make headway 是固定搭配，表示推进工作、取得进展。','解决测量问题后研究向前推进，体现进展义。'),M('The project made headway by losing its data, canceling every trial, and moving no closer to its goal.','The project made headway when the team fixed the sensor and resumed the trials.','失去数据并停掉试验意味着没有进展。'),[Q('headway',1,1,'To make headway on a task is to?','make progress toward completing it','walk backward without changing anything','hide the task from the team','headway 常指进展。'),Q('headway',2,1,'Which sentence uses headway naturally?','The negotiations made headway after both sides revised their offer.','The negotiations wore headway on their shoes.','The headway baked slowly in the oven.','make headway 是惯用搭配。'),Q('headway',3,1,'If a rescue boat makes little headway, it?','moves forward only slowly','has already reached the destination','is carrying a school principal','headway 也可指向前行进。'),Q('headway',4,1,'A team has made headway when it?','has solved part of the problem','has abandoned the goal entirely','has lost all records of its work','取得进展表示解决了部分问题。')]);
P('heady','Heady 由 head 加 -y 构成，形容强烈到令人兴奋、陶醉或头晕的影响，也可特指容易使人醉的酒饮。',C('heady.s2','饮品与酒精','The heady cider tasted sweet, but its high alcohol content soon made the unprepared guests dizzy.','这种烈苹果酒尝起来很甜，但高酒精度很快让毫无准备的客人头晕。','The heady cider tasted sweet / but its high alcohol content / soon made the unprepared guests dizzy.','heady 修饰 cider，指酒性强、容易令人醉；but 对比甜味与酒劲。','饮后很快头晕表明酒饮劲大。'),M('The heady cider contained no alcohol and could not affect anyone, even after a large glass.','The heady cider had enough alcohol to make a small glass feel strong.','不含酒精且毫无影响的饮料不能称为烈性 heady 酒饮。'),[Q('heady',1,1,'A heady success can make someone feel?','intensely excited or elated','sleepy because of low light','certain that nothing happened','heady 可形容令人兴奋陶醉。'),Q('heady',2,2,'A heady drink is likely to be?','strong enough to affect the drinker quickly','entirely alcohol-free','served only to children','饮品义表示酒劲大、容易使人醉。'),Q('heady',3,1,'Which situation could create a heady atmosphere?','a sudden victory and a cheering crowd','an ordinary quiet queue with no news','a blank room with no people','强烈兴奋的氛围可称 heady。'),Q('heady',4,2,'In “heady wine,” heady most nearly means?','intoxicating or strong','tasteless and watery','served in a tall glass only','此处指酒性强、易醉人。')]);
P('heal','Heal 源自古英语 hælan，与“完整、健康”相关；可指伤口自行愈合、治好病人，也可指平复创伤或弥合分歧。',C('heal.s3','关系修复','The two departments began to heal their rift by sharing data and agreeing on a single review schedule.','两个部门开始通过共享数据并统一审核日程来弥合分歧。','The two departments began to heal their rift / by sharing data / and agreeing on a single review schedule.','heal 作动词可接 rift 表示修复分歧；by 引出采取的办法。','合作行动逐步消除部门裂痕，体现比喻义。'),M('The meeting healed the rift by making both departments refuse to speak to each other.','The meeting helped heal the rift by getting both departments to discuss their concerns.','拒绝沟通会加深分歧，而不会修复裂痕。'),[Q('heal',1,1,'A cut heals when it?','becomes healthy again','turns into a new bone','is forgotten by someone else','伤口 heal 指逐渐愈合。'),Q('heal',2,2,'A doctor may heal a patient by?','treating the illness or injury','making the patient’s injury worse','hiding the diagnosis forever','及物义是治愈病人。'),Q('heal',3,3,'To heal a rift between friends is to?','repair the relationship or disagreement','make the disagreement permanent','move the friends to another country','比喻义可指弥合分歧。'),Q('heal',4,1,'Which sentence uses heal for a wound?','The burn began to heal after treatment.','The burn began to lead the committee.','The burn began to collect rent.','伤口好转是 heal 的字面义。')]);
P('healer','Healer 由 heal 加施事后缀 -er 构成，指治疗病人或帮助恢复健康的人，也可指有疗愈作用的事物。',C('healer.s1','护理与康复','The village healer cleaned the wound and urged the injured farmer to visit the clinic for further treatment.','村里的治疗者清理了伤口，并劝受伤的农夫去诊所接受进一步治疗。','The village healer cleaned the wound / and urged the injured farmer / to visit the clinic for further treatment.','healer 指施治者；urge sb to do 表示劝某人采取后续措施。','清理伤口并提出治疗建议的人符合治疗者义。'),M('The healer worsened every patient’s illness and refused to provide any care.','The healer treated the patients and referred serious cases to a clinic.','故意加重病情、不提供照护与治疗者角色相反。'),[Q('healer',1,1,'A healer is someone who?','helps sick or injured people recover','harvests crops for a living','writes titles above newspaper stories','healer 指治疗或帮助恢复的人。'),Q('healer',2,1,'Which person could be called a healer?','a nurse who treats wounds and supports recovery','a clerk who sells bus tickets','a hawker who calls out fruit prices','医护人员帮助伤病者恢复。'),Q('healer',3,1,'The noun healer is formed from?','heal plus an agent suffix','head plus a location suffix','haze plus a plural ending','heal + -er 构成施事名词。'),Q('healer',4,1,'A “natural healer” in a poem may be?','something believed to restore health','a tool for cutting hay','a sign at the top of a page','healer 也可指有疗愈作用之物。')]);
P('healing','Healing 由 heal 加 -ing 构成，作名词指伤病或心理创伤逐渐恢复的过程，也可修饰有助康复的事物。',C('healing.s1','伤病恢复','The doctor explained that healing would take several weeks and asked the patient to avoid lifting heavy boxes.','医生解释说，恢复需要数周，并要求病人避免搬重箱子。','The doctor explained / that healing would take several weeks / and asked the patient / to avoid lifting heavy boxes.','healing 作名词表示恢复过程；that 从句说明所需时间。','身体逐步恢复并需要休养，体现 healing 义。'),M('The healing of the fracture was complete before the bone had started to mend.','The healing of the fracture began as the bone gradually mended.','骨头尚未开始修复时，不能说骨折已经完全愈合。'),[Q('healing',1,1,'Healing is the process of?','becoming healthy again after injury or illness','making a healthy person ill','selling medical equipment','healing 指恢复健康的过程。'),Q('healing',2,1,'A healing period after surgery usually involves?','time for the body to recover','immediate heavy exercise without rest','removing all follow-up care','术后恢复需要时间。'),Q('healing',3,1,'A healing influence on a friendship might?','help repair hurt feelings','make every disagreement worse','prevent anyone from speaking','healing 也可形容有助于修复关系。'),Q('healing',4,1,'Which phrase is natural?','the healing of a broken bone','the healing of a newspaper headline into ink','the healing of a bus schedule into a road','伤骨恢复可用 healing。')]);
P('health','Health 源自古英语 hælth，与 hale、whole 的“完整、健全”相关，可指身心状况、免于疾病的状态，也可泛指医疗保健服务。',C('health.s1','身心状况','Regular sleep improved her health, and she had more energy for work and weekend walks.','规律睡眠改善了她的健康状况，使她工作和周末散步时更有精力。','Regular sleep improved her health / and she had more energy / for work and weekend walks.','health 是不可数名词，指整体身心状况；and 连接结果。','精力和日常状态变好说明整体健康改善。'),M('His health improved because his symptoms worsened and he could no longer leave bed.','His health improved as his symptoms eased and his strength returned.','症状加重且卧床不起说明健康恶化。'),[Q('health',1,1,'A person’s health refers broadly to their?','physical or mental condition','height above sea level','position in a company','health 可指身心状况。'),Q('health',2,2,'Good health often means being?','free from illness or in sound condition','unable to recover from any injury','unaware of one’s surroundings','health 也可指免于疾病的状态。'),Q('health',3,3,'Public health services are concerned with?','medical care and the health of communities','the repair of highways only','the sale of musical instruments','health 可泛指医疗保健服务。'),Q('health',4,1,'Which phrase is natural?','protect your health','harvest your health in a field','headquarter your health under a roof','protect your health 是自然搭配。')]);
P('health care','Health care 是 health 与 care 组成的名词短语，指为病人提供的医疗照护、诊断和治疗服务。',C('health care.s1','医疗服务','The rural clinic provides health care to families who would otherwise travel two hours to see a doctor.','这家乡村诊所为当地家庭提供医疗服务，否则他们得开车两小时才能看医生。','The rural clinic provides health care to families / who would otherwise travel two hours / to see a doctor.','health care 是不可数服务名词；who 从句说明服务对象的处境。','诊所提供诊疗服务，减少病人求医路程。'),M('The clinic provided health care by refusing to examine patients or offer any treatment.','The clinic provided health care by examining patients and arranging treatment.','拒绝检查和治疗不构成医疗照护。'),[Q('health care',1,1,'Health care includes services that?','prevent, diagnose, or treat illness','build houses for every family','teach only the history of music','health care 指医疗保健服务。'),Q('health care',2,1,'A rural clinic provides health care when it?','examines patients and offers treatment','sells furniture without medical staff','closes whenever someone is ill','诊疗与治疗属于医疗服务。'),Q('health care',3,1,'A patient seeks health care from a?','doctor, clinic, or hospital','harvest machine','newspaper headline','医疗照护通常由医护机构提供。'),Q('health care',4,1,'The phrase health care focuses on?','care and services related to people’s health','only a person’s eye color','a company’s central office','该短语关注健康相关服务。')]);
P('health club','Health club 由 health 与 club 组成，指提供健身器材、运动课程等设施的健身俱乐部。',C('health club.s1','运动与健身','The health club added an early-morning swimming class for members who wanted to exercise before work.','这家健身俱乐部为想在上班前锻炼的会员增开了清晨游泳课。','The health club added an early-morning swimming class / for members / who wanted to exercise before work.','health club 指提供锻炼设施或课程的场所；who 从句说明会员需求。','游泳课和会员锻炼体现健身俱乐部用途。'),M('She joined a health club to avoid all exercise and spend each visit watching television.','She joined a health club to use its pool and exercise classes.','健身俱乐部的主要用途是锻炼，而不是完全避免运动。'),[Q('health club',1,1,'A health club is a place mainly used for?','exercise and fitness activities','storing harvested grain','holding a court hearing','health club 指健身俱乐部。'),Q('health club',2,1,'Which facility might a health club offer?','exercise machines and swimming classes','a courtroom for legal trials','a hatchery for fish eggs','健身器材和课程属于俱乐部设施。'),Q('health club',3,1,'Someone joins a health club to?','work out and improve fitness','receive a newspaper headline','learn how to head a ship','会员通常来锻炼。'),Q('health club',4,1,'Health club differs from health care because it mainly provides?','fitness facilities rather than medical treatment','only emergency surgery','a company’s head office','健身俱乐部提供运动设施而非诊疗。')]);
P('healthcare','Healthcare 是 health 与 care 合写的形式，指医疗照护及相关服务体系，常作不可数名词或定语。',C('healthcare.s1','医疗体系','The report compared healthcare costs across three regions and found that preventive visits reduced emergency admissions.','报告比较了三个地区的医疗费用，发现预防性就诊减少了急诊入院。','The report compared healthcare costs across three regions / and found / that preventive visits reduced emergency admissions.','healthcare 修饰 costs，指医疗服务体系相关费用。','地区间医疗支出与预防治疗结果对应服务体系义。'),M('The healthcare system improved by denying patients every appointment and closing all clinics.','The healthcare system improved by expanding clinic access and preventive care.','拒绝所有患者并关闭诊所会损害医疗服务体系。'),[Q('healthcare',1,1,'Healthcare refers to?','medical services and the system that provides them','a kind of farm machinery','a person’s role as school principal','healthcare 指医疗服务及其体系。'),Q('healthcare',2,1,'A healthcare worker might be?','a nurse caring for patients','a hawker selling fruit','a sailor steering toward a headland','护士属于医疗照护人员。'),Q('healthcare',3,1,'Which sentence uses healthcare as a modifier?','The healthcare budget increased this year.','The healthfully budget increased this year.','The budget healthcare itself was blue.','healthcare 可作定语修饰 budget。'),Q('healthcare',4,1,'Healthcare and health care usually share which meaning?','services for people’s medical needs','sports headlines and newspaper titles','only the condition of a person’s hair','两种写法通常都指医疗服务。')]);
P('healthful','Healthful 由 health 加 -ful 构成，表示有益于健康、促进身体健康；常用于食物、习惯或环境。',C('healthful.s1','饮食与生活','The dietitian suggested a healthful lunch of beans, greens, and whole grains instead of a sugary drink and pastries.','营养师建议午餐吃豆类、绿叶菜和全谷物等有益健康的食物，而不是含糖饮料和点心。','The dietitian suggested a healthful lunch of beans, greens, and whole grains / instead of / a sugary drink and pastries.','healthful 修饰 lunch，表示这顿饭有益健康；instead of 对比替代方案。','富含豆类、蔬菜和全谷物的午餐有益健康。'),M('The dietitian called a lunch of spoiled meat and contaminated water healthful.','The dietitian called a balanced lunch of vegetables and beans healthful.','变质食物和受污染水有害健康。'),[Q('healthful',1,1,'A healthful habit is one that?','supports or improves health','causes illness deliberately','has no connection to well-being','healthful 表示有益于健康。'),Q('healthful',2,1,'Which lunch is most likely healthful?','beans, vegetables, and whole grains','spoiled meat and contaminated water','only candy and sugary soda','营养均衡的食物更有益健康。'),Q('healthful',3,1,'Healthful most nearly means?','beneficial to health','located at a company’s headquarters','difficult to hear','healthful 是“有益健康的”。'),Q('healthful',4,1,'A healthful environment might provide?','clean air and safe places to exercise','toxic fumes and unsafe drinking water','no access to daylight or rest','清洁空气与运动空间促进健康。')]);
P('healthy','Healthy 由 health 加 -y 构成，通常形容身体或心理状态良好、强健，也可形容有利于健康的生活方式或关系。',C('healthy.s1','身心状态','After several weeks of rest and treatment, the healthy-looking kitten returned to its playful routine.','经过数周休养和治疗后，这只看起来健康的小猫恢复了活泼的日常。','After several weeks of rest and treatment / the healthy-looking kitten / returned to its playful routine.','healthy 修饰 kitten；looking 使该判断明确为外观观察。','精力恢复并重新玩耍体现健康状态。'),M('The healthy patient was described as strong even though he was seriously ill and unable to stand.','The recovering patient looked healthy again after his strength returned.','重病且无法站立与强健的状态不符。'),[Q('healthy',1,1,'A healthy person is generally?','well and strong','severely ill and unable to function','unaware of their own name','healthy 指健康、强健。'),Q('healthy',2,1,'A healthy relationship is likely to include?','respectful communication and reasonable boundaries','constant threats and fear','refusal to listen to one another','健康关系具有尊重和沟通。'),Q('healthy',3,1,'Which food choice might support a healthy diet?','a balanced meal with vegetables and protein','spoiled food left unrefrigerated','only sugar at every meal','均衡饮食有利于健康。'),Q('healthy',4,1,'Healthy is the adjective related to the noun?','health','headquarters','harvest','healthy 与 health 相关。')]);
P('heap','Heap 源自古英语 heap，名词可指一堆东西或大量事物；作动词可指堆放，也可指装得满或大量给予。',C('heap.s4','量与赠予','The host heaped praise on the volunteers, naming each person who had worked through the night.','主人对志愿者大加赞扬，逐一提到每位通宵工作的成员。','The host heaped praise on the volunteers / naming each person / who had worked through the night.','heap praise on sb 是“大加赞扬”的搭配；naming 补充赞扬方式。','大量而热情地赞扬志愿者，体现“给予很多”义。'),M('The host heaped praise on the volunteers by refusing to say anything kind about their work.','The host heaped praise on the volunteers by publicly thanking them for their work.','拒绝说任何好话与“大加赞扬”相反。'),[Q('heap',1,1,'A heap of leaves is?','a pile of leaves','a single leaf on a branch','a row of empty flowerpots','heap 名词指堆、一堆。'),Q('heap',2,2,'“Heaps of time” means?','a large amount of time','exactly one second','no time at all','heaps 可表示大量。'),Q('heap',3,3,'To heap sand into a pile is to?','put it together in a mound','scatter every grain across a wide field','turn it into a liquid','heap 作动词可表示堆放。'),Q('heap',4,4,'To heap praise on a child is to?','praise the child generously','criticize the child once','hide the child’s work','heap sth on sb 可指大量给予。')]);
P('hear','Hear 源自古英语 hieran，既指用耳朵听见声音，也可指听说消息或正式听取陈述、意见。',C('hear.s3','法律程序','The committee will hear the witness’s account next week before deciding whether the complaint should proceed.','委员会将在下周听取证人的陈述，再决定是否继续处理投诉。','The committee will hear the witness’s account next week / before deciding / whether the complaint should proceed.','hear 作动词表示正式听取陈述；before 从句说明听证与决定的先后。','机构听取证词后再决定，体现正式审理义。'),M('The committee heard the witness by refusing to let her speak or submit evidence.','The committee heard the witness by inviting her to give evidence at the meeting.','拒绝发言和提交证据意味着没有听取证词。'),[Q('hear',1,1,'If you hear a bell, you?','receive its sound with your ears','see its color without looking','write a letter to its maker','hear 的基本义是听见声音。'),Q('hear',2,2,'“I heard that the road is closed” means?','I was told or learned that information','I personally closed the road','I listened to the road itself','hear 可指听说、得知消息。'),Q('hear',3,3,'A court may hear a case by?','listening to evidence and arguments','painting the courtroom walls','sending every witness home unheard','hear 可指正式听取案件陈述。'),Q('hear',4,1,'Which action shows someone heard the alarm?','they noticed its sound and responded','they read a silent sign only','they slept through it without noticing','听见警报意味着感知到声音。')]);
P('hearing','Hearing 由 hear 加 -ing 构成，可指听觉能力，也可指法院或委员会正式听取案件、证词的会议。',C('hearing.s1','听力检查','The clinic tested the patient’s hearing in a quiet room and compared the results with last year’s chart.','诊所在安静的房间里检测病人的听力，并将结果与去年的图表比较。','The clinic tested the patient’s hearing in a quiet room / and compared the results / with last year’s chart.','hearing 作名词表示听觉能力；test 的宾语是听力。','检测声音辨识能力体现听力义。'),M('The musician’s hearing improved when the clinic tested only her eyesight.','The musician’s hearing was assessed with tones played at different volumes.','只测视力不能证明听力有所改善。'),[Q('hearing',1,1,'A hearing test measures a person’s?','ability to detect sounds','ability to digest food','ability to read road signs','hearing 可指听觉能力。'),Q('hearing',2,1,'A court hearing is a meeting where?','a case or evidence is formally considered','music is recorded for an album','a ship enters a sheltered haven','hearing 也可指正式听证会。'),Q('hearing',3,1,'If someone has poor hearing, they may?','struggle to detect quiet sounds','be unable to smell flowers','have trouble lifting a box','听力差会难以听见微弱声音。'),Q('hearing',4,1,'Which phrase refers to a legal proceeding?','a hearing on the proposed law','hearing the alarm across the room','a hearing aid battery','讨论法律提案的 hearing 是听证会。')]);
P('hearsay','Hearsay 由 hear 与 say 组合，指从他人听来的说法或传闻；法律语境中常指非亲身证实的陈述。',C('hearsay.s1','证据与报道','The editor refused to publish the accusation as fact because it came from hearsay rather than a named eyewitness.','编辑拒绝把指控当作事实刊出，因为消息来自传闻，而不是具名目击者。','The editor refused to publish the accusation as fact / because it came from hearsay / rather than a named eyewitness.','hearsay 是不可数名词，指未经直接证实的传闻；rather than 对比证据来源。','消息不是目击者亲证，说明其传闻性质。'),M('The report was hearsay because the journalist personally witnessed the event and recorded it on video.','The report relied on hearsay because the journalist repeated an unverified story from an unknown source.','亲眼目击并录像不属于转述传闻。'),[Q('hearsay',1,1,'Hearsay is information?','repeated from what someone else said','personally measured with a calibrated tool','printed on a signed official record','hearsay 指听来的传闻。'),Q('hearsay',2,1,'Why might a court treat hearsay cautiously?','the speaker may not have witnessed the event directly','it is always recorded by several cameras','it is the same as a signed contract','传闻来源可能并非亲眼所见。'),Q('hearsay',3,1,'Which statement is hearsay?','“A neighbor told me that the bridge had closed.”','“I watched the bridge close at noon.”','“I measured the gate with a ruler.”','转述邻居的话而非亲见是 hearsay。'),Q('hearsay',4,1,'A journalist should verify hearsay before?','presenting it as established fact','checking whether the source exists','asking a witness for details','未经核实的传闻不应当作事实。')]);
P('heart','Heart 源自古英语 heorte，名词可指心脏、情感内心、情绪或勇气，也可指事物核心或地区中心。',[C('heart.s4','核心议题','At the heart of the dispute was a simple question: who would maintain the bridge after construction ended?','争端的核心是一个简单问题：工程结束后由谁维护这座桥？','At the heart of the dispute / was a simple question / who would maintain the bridge after construction ended.','at the heart of 表示某事的核心或实质；冒号后具体说明核心问题。','维护责任是整场争端最重要的议题。'),C('heart.s1','身体与健康','The doctor listened to the patient’s heart and checked that its rhythm remained steady during the exercise test.','医生听了病人的心音，并检查运动测试期间心律是否保持稳定。','The doctor listened to the patient’s heart / and checked / that its rhythm remained steady during the exercise test.','heart 指胸腔内泵血器官；its 指代心脏。','检查心律说明此处是器官义。')],M('The heart of the proposal was its decorative cover, while the main policy question was irrelevant.','The heart of the proposal was its central policy change, not the decorative cover.','heart 比喻最重要的核心，而不是装饰性封面。'),[Q('heart',1,1,'The heart is the organ that?','pumps blood through the body','filters air through the lungs','digests food in the stomach','heart 的器官义是泵血。'),Q('heart',2,2,'A kind heart suggests someone has?','compassionate feelings','a weak roof above the house','a fast running speed only','heart 可指情感、内心。'),Q('heart',3,3,'“She lost heart after the setback” means she lost?','courage or enthusiasm','her physical heart','the central street of town','lose heart 表示失去勇气或信心。'),Q('heart',4,5,'The heart of a forest is?','its central area','the loudest bird in it','the edge farthest from the trees','heart 可指地区或事物中心。')]);

})();
